return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'ਵੂਕਾੱਮਰਸ','Go to Plugin Search' => 'ਪਲੱਗਇਨ ਖੋਜ &#39;ਤੇ ਜਾਓ','Activate %s' => '%s ਨੂੰ ਸਰਗਰਮ ਕਰੋ','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s ਨੂੰ</strong> <strong>%2$s ਨੂੰ</strong> ਸਥਾਪਤ ਅਤੇ ਕਿਰਿਆਸ਼ੀਲ ਕਰਨ ਦੀ ਲੋੜ ਹੈ। <a href="%4$s">%3$s</a>','Enter your code here' => 'ਇੱਥੇ ਆਪਣਾ ਕੋਡ ਦਰਜ ਕਰੋ।','Add %s' => '%s ਜੋੜੋ','Remove' => 'ਹਟਾਓ','Order number and receipt will be sent to this email address.' => 'ਆਰਡਰ ਨੰਬਰ ਅਤੇ ਰਸੀਦ ਇਸ ਈਮੇਲ ਪਤੇ &#39;ਤੇ ਭੇਜੀ ਜਾਵੇਗੀ।','Apartment, unit, building, floor, etc.' => 'ਅਪਾਰਟਮੈਂਟ, ਯੂਨਿਟ, ਇਮਾਰਤ, ਫਰਸ਼, ਆਦਿ।','Shipping phone' => 'ਸ਼ਿਪਿੰਗ ਫ਼ੋਨ','Only used for shipping-related questions.' => 'ਸਿਰਫ਼ ਸ਼ਿਪਿੰਗ-ਸਬੰਧਤ ਸਵਾਲਾਂ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।','Single step' => 'ਇੱਕ ਕਦਮ','Click to go to the order summary' => 'ਆਰਡਰ ਸਾਰਾਂਸ਼ &#39;ਤੇ ਜਾਣ ਲਈ ਕਲਿੱਕ ਕਰੋ','Cart total:' => 'ਕਾਰਟ ਕੁੱਲ:','Proceed to %s' => '%s ਤੱਕ ਅੱਗੇ ਵਧੋ','Proceed to contact' => 'ਸੰਪਰਕ ਕਰਨ ਲਈ ਅੱਗੇ ਵਧੋ','Proceed to shipping' => 'ਸ਼ਿਪਿੰਗ ਲਈ ਅੱਗੇ ਵਧੋ','Proceed to billing' => 'ਬਿਲਿੰਗ &#39;ਤੇ ਅੱਗੇ ਵਧੋ','Proceed to payment' => 'ਭੁਗਤਾਨ ਲਈ ਅੱਗੇ ਵਧੋ','Shipping method' => 'ਸ਼ਿਪਿੰਗ ਵਿਧੀ','Additional notes' => 'ਵਾਧੂ ਨੋਟਸ','Payment method' => 'ਭੁਗਤਾਨੇ ਦੇ ਢੰਗ','Step %1$s of %2$s' => '%2$s ਵਿੱਚੋਂ %1$s ਕਦਮ','Change: %s' => 'ਬਦਲਾਅ: %s','Not selected yet.' => 'ਅਜੇ ਚੁਣਿਆ ਨਹੀਂ ਗਿਆ।','Same as shipping address' => 'ਸ਼ਿਪਿੰਗ ਪਤੇ ਦੇ ਸਮਾਨ','Same as billing address' => 'ਬਿਲਿੰਗ ਪਤੇ ਦੇ ਸਮਾਨ','Order summary' => 'ਆਰਡਰ ਸਾਰਾਂਸ਼','Edit cart' => 'ਕਾਰਟ ਸੰਪਾਦਿਤ ਕਰੋ','Did you mean %s?' => 'ਕੀ ਤੁਹਾਡਾ ਮਤਲਬ %s ਸੀ?','Change email address to: {suggestion-value}' => 'ਈਮੇਲ ਪਤਾ ਇਸ ਵਿੱਚ ਬਦਲੋ: {suggestion-value}','This is a required field.' => 'ਇਹ ਇੱਕ ਲੋੜੀਂਦਾ ਖੇਤਰ ਹੈ।','This is not a valid email address.' => 'ਇਹ ਇੱਕ ਵੈਧ ਈਮੇਲ ਪਤਾ ਨਹੀਂ ਹੈ।','This field does not match the related field value.' => 'ਇਹ ਖੇਤਰ ਸੰਬੰਧਿਤ ਖੇਤਰ ਮੁੱਲ ਨਾਲ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ।','The CPF number "{cpf_number}" is invalid.' => 'CPF ਨੰਬਰ &quot;{cpf_number}&quot; ਅਵੈਧ ਹੈ।','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ ਨੰਬਰ &quot;{cnpj_number}&quot; ਅਵੈਧ ਹੈ।','(Required)' => '(ਲੋੜੀਂਦਾ)','Checkout Header - Desktop' => 'ਚੈੱਕਆਉਟ ਹੈਡਰ - ਡੈਸਕਟਾਪ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'ਵੱਡੀਆਂ ਸਕ੍ਰੀਨਾਂ ਲਈ ਚੈੱਕਆਉਟ ਹੈੱਡਰ &#39;ਤੇ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ। ਸਿਰਫ਼ ਤਾਂ ਹੀ ਪ੍ਰਦਰਸ਼ਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਜੇਕਰ ਪਲੱਗਇਨ ਦੇ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਜਾ ਰਹੀ ਹੋਵੇ।','Checkout Header - Mobile' => 'ਚੈੱਕਆਉਟ ਹੈਡਰ - ਮੋਬਾਈਲ','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'ਮੋਬਾਈਲ ਡਿਵਾਈਸਾਂ ਲਈ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਦੇ ਹੇਠਾਂ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ। ਸਿਰਫ਼ ਤਾਂ ਹੀ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ ਜੇਕਰ ਪਲੱਗਇਨ ਦੇ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਜਾ ਰਹੀ ਹੋਵੇ।','Checkout Sidebar' => 'ਚੈੱਕਆਉਟ ਸਾਈਡਬਾਰ','Display widgets on the checkout sidebar after the order summary.' => 'ਆਰਡਰ ਸਾਰਾਂਸ਼ ਤੋਂ ਬਾਅਦ ਚੈੱਕਆਉਟ ਸਾਈਡਬਾਰ &#39;ਤੇ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','Checkout Order Summary' => 'ਚੈੱਕਆਉਟ ਆਰਡਰ ਸਾਰਾਂਸ਼','Display widgets inside the order summary at the checkout page.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਆਰਡਰ ਸੰਖੇਪ ਦੇ ਅੰਦਰ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','Checkout Below Place Order' => 'ਹੇਠਾਂ ਚੈੱਕਆਉਟ ਕਰੋ ਆਰਡਰ ਦਿਓ','Display widgets below the place order button at the checkout page.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਪਲੇਸ ਆਰਡਰ ਬਟਨ ਦੇ ਹੇਠਾਂ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','Checkout Footer' => 'ਚੈੱਕਆਉਟ ਫੁੱਟਰ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ਚੈੱਕਆਉਟ ਫੁੱਟਰ &#39;ਤੇ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ। ਸਿਰਫ਼ ਤਾਂ ਹੀ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ ਜੇਕਰ ਪਲੱਗਇਨ ਦੇ ਚੈੱਕਆਉਟ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਜਾ ਰਹੀ ਹੋਵੇ।','Classic' => 'ਕਲਾਸਿਕ','Boxed' => 'ਡੱਬੇ ਵਾਲਾ','Split' => 'ਵੰਡ','Minimalist' => 'ਘੱਟੋ-ਘੱਟ','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz ਦੁਆਰਾ ਤਰਲ ਚੈੱਕਆਉਟ ਅਤੇ ਡਿਲੀਵਰੀ ਮਿਤੀ ਪਲੱਗਇਨ','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>ਸਾਨੂੰ ਪਤਾ ਲੱਗਿਆ ਹੈ ਕਿ ਤੁਸੀਂ CodeRockz ਦੁਆਰਾ WooCommerce (ਮੁਫ਼ਤ ਅਤੇ PRO) ਲਈ ਪਲੱਗਇਨ ਡਿਲੀਵਰੀ ਅਤੇ ਪਿਕਅੱਪ ਮਿਤੀ ਸਮਾਂ ਵਰਤ ਰਹੇ ਹੋ। ਇਹਨਾਂ ਪਲੱਗਇਨਾਂ ਨਾਲ ਏਕੀਕਰਨ ਨੂੰ Fluid Checkout PRO ਵਿੱਚ ਤਬਦੀਲ ਕਰ ਦਿੱਤਾ ਗਿਆ ਹੈ।</p>','Upgrade to PRO' => 'PRO ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ','Fluid Checkout database updated successfully' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਡੇਟਾਬੇਸ ਸਫਲਤਾਪੂਰਵਕ ਅੱਪਡੇਟ ਕੀਤਾ ਗਿਆ','The database changes where applied successfully.' => 'ਜਿੱਥੇ ਸਫਲਤਾਪੂਰਵਕ ਲਾਗੂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਉੱਥੇ ਡਾਟਾਬੇਸ ਬਦਲ ਜਾਂਦਾ ਹੈ।','Dismiss' => 'ਖਾਰਜ ਕਰੋ','Fluid Checkout database update' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਡੇਟਾਬੇਸ ਅੱਪਡੇਟ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ਡੇਟਾਬੇਸ ਵਿੱਚ ਕੁਝ ਬਦਲਾਅ ਜ਼ਰੂਰੀ ਹਨ। ਕਿਸੇ ਵੀ ਅੱਪਡੇਟ ਵਾਂਗ, ਅਸੀਂ ਤੁਹਾਨੂੰ <strong>ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀ ਵੈੱਬਸਾਈਟ ਦਾ ਪੂਰਾ ਬੈਕਅੱਪ ਲੈਣ</strong> ਦੀ ਸਿਫਾਰਸ਼ ਕਰਦੇ ਹਾਂ।','Update database' => 'ਡਾਟਾਬੇਸ ਅੱਪਡੇਟ ਕਰੋ','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ, ਡਿਵੀ ਬਿਲਡਰ ਚੈੱਕਆਉਟ ਲੇਆਉਟ ਦੇ ਅਨੁਕੂਲ ਨਹੀਂ ਹੈ।','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨੂੰ ਕੰਮ ਕਰਨ ਲਈ ਕਲਾਸਿਕ WooCommerce ਸ਼ਾਰਟਕੋਡ-ਅਧਾਰਿਤ ਚੈੱਕਆਉਟ ਫਾਰਮ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਚੈੱਕਆਉਟ ਪੰਨੇ ਦੀ ਦਿੱਖ ਅਤੇ ਅਹਿਸਾਸ ਨੂੰ ਅਨੁਕੂਲਿਤ ਕਰਨ ਲਈ Divi ਬਿਲਡਰ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ, ਚੈੱਕਆਉਟ ਪੰਨੇ ਦੇ ਹਰੇਕ ਹਿੱਸੇ ਲਈ ਕਲਾਸਿਕ ਸ਼ਾਰਟਕੋਡਾਂ ਨੂੰ Divi ਬਿਲਡਰ ਤੋਂ ਕਸਟਮ ਵਿਜੇਟਸ ਨਾਲ ਬਦਲ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ। ਇਹ ਕਸਟਮ ਵਿਜੇਟ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੇ ਅਨੁਕੂਲ ਨਹੀਂ ਹਨ।</p><p> ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੇ ਚੈੱਕਆਉਟ ਪੰਨੇ ਨੂੰ Divi ਬਿਲਡਰ ਵਿਜੇਟਸ ਦੀ ਥਾਂ &#39;ਤੇ ਇੱਕ ਟੈਕਸਟ ਵਿਜੇਟ ਨਾਲ ਸੰਪਾਦਿਤ ਕਰੋ ਜਿਸ ਵਿੱਚ ਸ਼ਾਰਟਕੋਡ <code>[woocommerce_checkout]</code> ਹੈ।</p>','Edit the checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਨੂੰ ਸੰਪਾਦਿਤ ਕਰੋ','Read the documentation.' => 'ਦਸਤਾਵੇਜ਼ ਪੜ੍ਹੋ।','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਜਰਮਨਾਈਜ਼ਡ ਪ੍ਰੋ ਮਲਟੀਸਟੈਪ ਚੈੱਕਆਉਟ ਵਿਸ਼ੇਸ਼ਤਾ ਨੂੰ ਅਯੋਗ ਕਰਨ ਦੀ ਲੋੜ ਹੈ','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ, ਜਰਮਨਾਈਜ਼ਡ ਪ੍ਰੋ ਪਲੱਗਇਨ ਤੋਂ ਮਲਟੀਸਟੈਪ ਵਿਸ਼ੇਸ਼ਤਾ ਬੇਲੋੜੀ ਹੋ ਜਾਂਦੀ ਹੈ ਅਤੇ <strong>ਨਵੇਂ ਆਰਡਰਾਂ ਦੀ ਪ੍ਰਕਿਰਿਆ ਕਰਦੇ ਸਮੇਂ ਗੰਭੀਰ ਗਲਤੀਆਂ ਦਾ</strong> ਕਾਰਨ ਬਣ ਸਕਦੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਪਲੱਗਇਨ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਜਰਮਨਾਈਜ਼ਡ ਪ੍ਰੋ ਮਲਟੀਸਟੈਪ ਚੈੱਕਆਉਟ ਵਿਸ਼ੇਸ਼ਤਾ ਨੂੰ ਅਯੋਗ ਕਰੋ।','Go to Germanized settings' => 'ਜਰਮਨਾਈਜ਼ਡ ਸੈਟਿੰਗਾਂ &#39;ਤੇ ਜਾਓ।','Thanks for choosing Fluid Checkout!' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਚੁਣਨ ਲਈ ਧੰਨਵਾਦ!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'ਤੁਸੀਂ ਇਸ ਪਲੱਗਇਨ ਨੂੰ ਕਾਫ਼ੀ ਸਮੇਂ ਤੋਂ ਵਰਤ ਰਹੇ ਹੋ। ਤੁਹਾਨੂੰ ਹੁਣ ਤੱਕ ਇਹ ਕਿਵੇਂ ਲੱਗਿਆ?<br> ਕਿਰਪਾ ਕਰਕੇ ਸਾਨੂੰ ਇੱਕ ਤੇਜ਼ ਰੇਟਿੰਗ ਦਿਓ, ਅਸੀਂ ਹਰ ਫੀਡਬੈਕ ਦੀ ਕਦਰ ਕਰਦੇ ਹਾਂ ਅਤੇ ਇਹ ਸਾਨੂੰ ਪਲੱਗਇਨ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਂਦੇ ਰਹਿਣ ਲਈ ਉਤਸ਼ਾਹਿਤ ਕਰਦਾ ਹੈ :)','Rate the plugin' => 'ਪਲੱਗਇਨ ਨੂੰ ਦਰਜਾ ਦਿਓ','I need help!' => 'ਮੈਨੂੰ ਮਦਦ ਚਾਹੀਦੀ ਹੈ!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Fluid Checkout ਨਾਲ ਇਸਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ Quadlayers ਦੁਆਰਾ WooCommerce Checkout Manager ਦੀਆਂ ਕੁਝ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਉਮੀਦ ਅਨੁਸਾਰ ਕੰਮ ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ। ਵਧੇਰੇ ਜਾਣਕਾਰੀ ਅਤੇ ਵਿਕਲਪਿਕ ਹੱਲਾਂ ਲਈ <a href="%s">ਸਾਡੇ ਦਸਤਾਵੇਜ਼</a> ਪੜ੍ਹੋ।','Read documentation' => 'ਦਸਤਾਵੇਜ਼ ਪੜ੍ਹੋ','Don\'t show this again' => 'ਇਸਨੂੰ ਦੁਬਾਰਾ ਨਾ ਦਿਖਾਓ','Fluid Checkout PRO' => 'ਤਰਲ ਚੈੱਕਆਉਟ ਪ੍ਰੋ','More design templates' => 'ਹੋਰ ਡਿਜ਼ਾਈਨ ਟੈਂਪਲੇਟ','Optimized cart page' => 'ਅਨੁਕੂਲਿਤ ਕਾਰਟ ਪੰਨਾ','Optimized order received / thank you page' => 'ਅਨੁਕੂਲਿਤ ਆਰਡਰ ਪ੍ਰਾਪਤ ਹੋਇਆ / ਧੰਨਵਾਦ ਪੰਨਾ','Edit cart contents at checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਕਾਰਟ ਸਮੱਗਰੀ ਨੂੰ ਸੰਪਾਦਿਤ ਕਰੋ','Account matching / user matching' => 'ਖਾਤਾ ਮਿਲਾਨ / ਉਪਭੋਗਤਾ ਮਿਲਾਨ','Trust symbols on the cart and thank you pages' => 'ਕਾਰਟ ਅਤੇ ਧੰਨਵਾਦ ਪੰਨਿਆਂ &#39;ਤੇ ਵਿਸ਼ਵਾਸ ਚਿੰਨ੍ਹ','More positions for the coupon code on the checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਕੂਪਨ ਕੋਡ ਲਈ ਹੋਰ ਸਥਿਤੀਆਂ','International phone numbers' => 'ਅੰਤਰਰਾਸ਼ਟਰੀ ਫ਼ੋਨ ਨੰਬਰ','Gift messages and packing slips' => 'ਤੋਹਫ਼ੇ ਦੇ ਸੁਨੇਹੇ ਅਤੇ ਪੈਕਿੰਗ ਸਲਿੱਪਾਂ','Local pickup and in-store collection' => 'ਸਥਾਨਕ ਪਿਕਅੱਪ ਅਤੇ ਸਟੋਰ ਵਿੱਚ ਸੰਗ੍ਰਹਿ','EU-VAT Assistant' => 'EU-VAT ਸਹਾਇਕ','I already have it – Hide this offer' => 'ਮੇਰੇ ਕੋਲ ਇਹ ਪਹਿਲਾਂ ਹੀ ਹੈ - ਇਸ ਪੇਸ਼ਕਸ਼ ਨੂੰ ਲੁਕਾਓ','Activated' => 'ਕਿਰਿਆਸ਼ੀਲ','Address book' => 'ਐਡਰੈੱਸ ਬੁੱਕ','Select an image' => 'ਇੱਕ ਚਿੱਤਰ ਚੁਣੋ','Cart layout' => 'ਕਾਰਟ ਲੇਆਉਟ','Cart optimizations' => 'ਕਾਰਟ ਅਨੁਕੂਲਤਾ','Enable cart page optimizations' => 'ਕਾਰਟ ਪੰਨਾ ਅਨੁਕੂਲਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Header and footer template' => 'ਹੈਡਰ ਅਤੇ ਫੁੱਟਰ ਟੈਂਪਲੇਟ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ਇਹ ਕੰਟਰੋਲ ਕਰਦਾ ਹੈ ਕਿ ਭਟਕਣਾ-ਮੁਕਤ ਪੰਨੇ ਦੇ ਸਿਰਲੇਖ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਨੀ ਹੈ ਜਾਂ ਮੌਜੂਦਾ ਕਿਰਿਆਸ਼ੀਲ ਥੀਮ ਦੇ ਸਿਰਲੇਖ ਅਤੇ ਫੁੱਟਰ ਨੂੰ ਰੱਖਣਾ ਹੈ।','Distraction free header and footer' => 'ਭਟਕਣਾ-ਮੁਕਤ ਹੈਡਰ ਅਤੇ ਫੁੱਟਰ','Theme\'s header and footer' => 'ਥੀਮ ਦਾ ਹੈੱਡਰ ਅਤੇ ਫੁੱਟਰ','Cart elements' => 'ਕਾਰਟ ਦੇ ਤੱਤ','Make the order summary stay visible on the cart page while scrolling' => 'ਸਕ੍ਰੌਲ ਕਰਦੇ ਸਮੇਂ ਆਰਡਰ ਸੰਖੇਪ ਨੂੰ ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਦਿਖਾਈ ਦੇਣ ਦਿਓ।','Coupon codes' => 'ਕੂਪਨ ਕੋਡ','Hidden' => 'ਲੁਕਿਆ ਹੋਇਆ','Before the cart items section' => 'ਕਾਰਟ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ','Inside the cart items section' => 'ਕਾਰਟ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਦੇ ਅੰਦਰ','After the cart items section' => 'ਕਾਰਟ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਤੋਂ ਬਾਅਦ','Before the shipping section' => 'ਸ਼ਿਪਿੰਗ ਸੈਕਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ','After the shipping section' => 'ਸ਼ਿਪਿੰਗ ਸੈਕਸ਼ਨ ਤੋਂ ਬਾਅਦ','Before the order summary' => 'ਆਰਡਰ ਸੰਖੇਪ ਤੋਂ ਪਹਿਲਾਂ','Inside the order summary' => 'ਆਰਡਰ ਸਾਰਾਂਸ਼ ਦੇ ਅੰਦਰ','Before the order totals' => 'ਆਰਡਰ ਦੇ ਕੁੱਲ ਤੋਂ ਪਹਿਲਾਂ','After the order totals' => 'ਆਰਡਰ ਦੇ ਕੁੱਲ ਤੋਂ ਬਾਅਦ','After the order summary' => 'ਆਰਡਰ ਸੰਖੇਪ ਤੋਂ ਬਾਅਦ','Shipping' => 'ਸ਼ਿਪਿੰਗ','Select position where to display the shipping costs and calculator on the cart page.' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਸ਼ਿਪਿੰਗ ਲਾਗਤਾਂ ਅਤੇ ਕੈਲਕੁਲੇਟਰ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਵਾਲੀ ਸਥਿਤੀ ਚੁਣੋ।','Display as a cart section' => 'ਕਾਰਟ ਸੈਕਸ਼ਨ ਵਜੋਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Cross-sells' => 'ਕਰਾਸ-ਸੇਲ','Select position where to display the cross-sells section on the cart page.' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਕਰਾਸ-ਸੇਲਜ਼ ਸੈਕਸ਼ਨ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਵਾਲੀ ਸਥਿਤੀ ਚੁਣੋ।','Before the cart actions' => 'ਕਾਰਟ ਕਾਰਵਾਈਆਂ ਤੋਂ ਪਹਿਲਾਂ','After the cart actions' => 'ਕਾਰਟ ਕਾਰਵਾਈਆਂ ਤੋਂ ਬਾਅਦ','Layout of cross-sell items on the cart page.' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਕਰਾਸ-ਸੇਲ ਆਈਟਮਾਂ ਦਾ ਲੇਆਉਟ।','Optimized horizontal cross-sells layout' => 'ਅਨੁਕੂਲਿਤ ਖਿਤਿਜੀ ਕਰਾਸ-ਸੇਲ ਲੇਆਉਟ','Theme\'s cross-sells layout' => 'ਥੀਮ ਦਾ ਕਰਾਸ-ਸੇਲਜ਼ ਲੇਆਉਟ','Number of cross-sell items to display on the cart page' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਕਰਾਸ-ਸੇਲ ਆਈਟਮਾਂ ਦੀ ਗਿਣਤੀ','Add widget areas to the cart page' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਵਿਜੇਟ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'ਇਹਨਾਂ ਵਿਜੇਟ ਖੇਤਰਾਂ ਦੀ ਵਰਤੋਂ ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਟਰੱਸਟ ਚਿੰਨ੍ਹ ਅਤੇ ਟਰੱਸਟ ਬੈਜ ਜੋੜਨ ਲਈ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।','Checkout' => 'ਕਮਰਾ ਛੱਡ ਦਿਓ','Checkout layout' => 'ਚੈੱਕਆਉਟ ਲੇਆਉਟ','Design template' => 'ਡਿਜ਼ਾਈਨ ਟੈਂਪਲੇਟ','Dark mode' => 'ਡਾਰਕ ਮੋਡ','Enable dark mode' => 'ਡਾਰਕ ਮੋਡ ਚਾਲੂ ਕਰੋ','Logo image' => 'ਲੋਗੋ ਚਿੱਤਰ','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਦੇ ਸਿਰਲੇਖ &#39;ਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਇੱਕ ਚਿੱਤਰ ਚੁਣੋ। ਸਿਰਫ਼ ਭਟਕਣਾ-ਮੁਕਤ ਸਿਰਲੇਖ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','Header background color' => 'ਸਿਰਲੇਖ ਦੀ ਪਿੱਠਭੂਮੀ ਦਾ ਰੰਗ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਦੇ ਸਿਰਲੇਖ ਲਈ ਇੱਕ ਪਿਛੋਕੜ ਰੰਗ ਚੁਣੋ। ਸਿਰਫ਼ ਭਟਕਣਾ-ਮੁਕਤ ਸਿਰਲੇਖ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','HTML color value. ie: #f3f3f3' => 'HTML ਰੰਗ ਮੁੱਲ। ਭਾਵ: #f3f3f3','Page background color' => 'ਪੰਨੇ ਦੀ ਪਿੱਠਭੂਮੀ ਦਾ ਰੰਗ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਲਈ ਇੱਕ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਚੁਣੋ। ਰੰਗ <em>ਬਾਡੀ</em> ਐਲੀਮੈਂਟ &#39;ਤੇ ਲਾਗੂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।','Footer background color' => 'ਫੁੱਟਰ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ਚੈੱਕਆਉਟ ਪੇਜ ਫੁੱਟਰ ਲਈ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਚੁਣੋ। ਇਹ ਸਿਰਫ਼ ਭਟਕਣਾ-ਮੁਕਤ ਹੈੱਡਰ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','Progress bar' => 'ਪ੍ਰਗਤੀ ਪੱਟੀ','Display the checkout progress bar when using multi-step checkout layout' => 'ਮਲਟੀ-ਸਟੈਪ ਚੈੱਕਆਉਟ ਲੇਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਚੈੱਕਆਉਟ ਪ੍ਰਗਤੀ ਪੱਟੀ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Make the checkout progress bar stay visible while scrolling' => 'ਸਕ੍ਰੌਲ ਕਰਦੇ ਸਮੇਂ ਚੈੱਕਆਉਟ ਪ੍ਰਗਤੀ ਪੱਟੀ ਨੂੰ ਦ੍ਰਿਸ਼ਮਾਨ ਰੱਖੋ','Express checkout' => 'ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ','Enable the express checkout section' => 'ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ ਸੈਕਸ਼ਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'ਜਦੋਂ ਸਮਰਥਿਤ ਭੁਗਤਾਨ ਗੇਟਵੇ &#39;ਤੇ ਇਹ ਵਿਸ਼ੇਸ਼ਤਾ ਸਮਰੱਥ ਹੁੰਦੀ ਹੈ ਤਾਂ ਚੈੱਕਆਉਟ &#39;ਤੇ ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ ਸੈਕਸ਼ਨ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਦਾ ਹੈ।','Display express checkout buttons in one line for larger screens' => 'ਵੱਡੀਆਂ ਸਕ੍ਰੀਨਾਂ ਲਈ ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ ਬਟਨਾਂ ਨੂੰ ਇੱਕ ਲਾਈਨ ਵਿੱਚ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'ਇੱਕ ਅਨੁਕੂਲ ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ ਭੁਗਤਾਨ ਗੇਟਵੇ ਨਾਲ ਭੁਗਤਾਨ ਕਰਦੇ ਸਮੇਂ ਵਾਧੂ ਚੈੱਕਆਉਟ ਲੋੜੀਂਦੇ ਖੇਤਰਾਂ ਨੂੰ ਅਣਡਿੱਠ ਕਰੋ।','Make the order summary stay visible while scrolling' => 'ਸਕ੍ਰੌਲ ਕਰਦੇ ਸਮੇਂ ਆਰਡਰ ਦੇ ਸੰਖੇਪ ਨੂੰ ਦ੍ਰਿਸ਼ਮਾਨ ਰੱਖੋ','Choose a background color for the order summary section.' => 'ਆਰਡਰ ਸੰਖੇਪ ਭਾਗ ਲਈ ਇੱਕ ਪਿਛੋਕੜ ਰੰਗ ਚੁਣੋ।','Highlight the order totals row in the order summary table' => 'ਆਰਡਰ ਸੰਖੇਪ ਸਾਰਣੀ ਵਿੱਚ ਆਰਡਰ ਕੁੱਲ ਕਤਾਰ ਨੂੰ ਉਜਾਗਰ ਕਰੋ।','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ਜਦੋਂ ਆਰਡਰ ਸੰਖੇਪ ਭਾਗ ਵਿੱਚ ਹਾਈਲਾਈਟ ਕੀਤਾ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਨਹੀਂ ਹੁੰਦਾ ਤਾਂ ਇਹ ਸਭ ਤੋਂ ਵੱਧ ਉਪਯੋਗੀ ਹੁੰਦਾ ਹੈ। ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਪ੍ਰੋ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਕਾਰਟ, ਆਰਡਰ ਪ੍ਰਾਪਤ ਅਤੇ ਵੇਖੋ ਆਰਡਰ ਪੰਨਿਆਂ &#39;ਤੇ ਵੀ ਲਾਗੂ ਹੋ ਸਕਦਾ ਹੈ।','Action link on the order summary at checkout.' => 'ਚੈੱਕਆਉਟ ਵੇਲੇ ਆਰਡਰ ਸਾਰਾਂਸ਼ &#39;ਤੇ ਕਾਰਵਾਈ ਲਿੰਕ।','Edit cart link' => 'ਕਾਰਟ ਲਿੰਕ ਦਾ ਸੰਪਾਦਨ ਕਰੋ','Cart items count' => 'ਕਾਰਟ ਆਈਟਮਾਂ ਦੀ ਗਿਣਤੀ','Link to shop page' => 'ਦੁਕਾਨ ਪੰਨੇ ਦਾ ਲਿੰਕ','Cart items' => 'ਕਾਰਟ ਆਈਟਮਾਂ','Hide cart items errors at the checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਕਾਰਟ ਆਈਟਮਾਂ ਦੀਆਂ ਗਲਤੀਆਂ ਲੁਕਾਓ','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਦੇ ਸਿਖਰ &#39;ਤੇ ਕਾਰਟ ਆਈਟਮਾਂ ਦੇ ਗਲਤੀ ਸੁਨੇਹੇ ਨੂੰ ਨਾ ਦਿਖਾਓ। ਖਰੀਦਦਾਰੀ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਚੈੱਕਆਉਟ ਫਾਰਮ ਜਮ੍ਹਾਂ ਕਰਦੇ ਸਮੇਂ, ਇਹ ਗਲਤੀ ਸੁਨੇਹੇ ਹਮੇਸ਼ਾ ਪ੍ਰਦਰਸ਼ਿਤ ਹੋਣਗੇ।','Place order' => 'ਆਰਡਰ ਦਿਓ','Define the position to display "Place order" and terms checkbox section.' => '&quot;ਪਲੇਸ ਆਰਡਰ&quot; ਅਤੇ ਸ਼ਰਤਾਂ ਚੈੱਕਬਾਕਸ ਭਾਗ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਸਥਿਤੀ ਨੂੰ ਪਰਿਭਾਸ਼ਿਤ ਕਰੋ।','Some options might not be compatible with some plugins and themes.' => 'ਕੁਝ ਵਿਕਲਪ ਕੁਝ ਪਲੱਗਇਨਾਂ ਅਤੇ ਥੀਮਾਂ ਦੇ ਅਨੁਕੂਲ ਨਹੀਂ ਹੋ ਸਕਦੇ ਹਨ।','Below the payment section' => 'ਭੁਗਤਾਨ ਭਾਗ ਦੇ ਹੇਠਾਂ','Below the order summary' => 'ਆਰਡਰ ਸਾਰਾਂਸ਼ ਦੇ ਹੇਠਾਂ','Both below the payment section and the order summary' => 'ਭੁਗਤਾਨ ਭਾਗ ਦੇ ਹੇਠਾਂ ਅਤੇ ਆਰਡਰ ਸਾਰਾਂਸ਼ ਦੋਵੇਂ','Add widget areas to the checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਵਿਜੇਟ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ਇਹਨਾਂ ਵਿਜੇਟ ਖੇਤਰਾਂ ਦੀ ਵਰਤੋਂ ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਟਰੱਸਟ ਚਿੰਨ੍ਹ ਅਤੇ ਟਰੱਸਟ ਬੈਜ ਜੋੜਨ ਲਈ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।','Display the coupon codes section title' => 'ਕੂਪਨ ਕੋਡ ਭਾਗ ਸਿਰਲੇਖ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Select position where to display the coupon codes section on the checkout page.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਕੂਪਨ ਕੋਡ ਸੈਕਸ਼ਨ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਦੀ ਸਥਿਤੀ ਚੁਣੋ।','Before the checkout steps' => 'ਚੈੱਕਆਉਟ ਕਦਮਾਂ ਤੋਂ ਪਹਿਲਾਂ','As a substep before payment methods' => 'ਭੁਗਤਾਨ ਵਿਧੀਆਂ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਉਪ-ਕਦਮ ਵਜੋਂ','As a substep after payment methods' => 'ਭੁਗਤਾਨ ਵਿਧੀਆਂ ਤੋਂ ਬਾਅਦ ਇੱਕ ਉਪ-ਕਦਮ ਵਜੋਂ','Default button style' => 'ਡਿਫਾਲਟ ਬਟਨ ਸਟਾਈਲ','"Add" link button' => '&quot;ਜੋੜੋ&quot; ਲਿੰਕ ਬਟਨ','Checkout fields' => 'ਚੈੱਕਆਉਟ ਖੇਤਰ','Optional fields' => 'ਵਿਕਲਪਿਕ ਖੇਤਰ','Hide optional fields behind a link button' => 'ਲਿੰਕ ਬਟਨ ਦੇ ਪਿੱਛੇ ਵਿਕਲਪਿਕ ਖੇਤਰਾਂ ਨੂੰ ਲੁਕਾਓ','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ਖੁੱਲ੍ਹੇ ਇਨਪੁਟ ਖੇਤਰਾਂ ਦੀ ਗਿਣਤੀ ਘਟਾਉਣ ਲਈ ਇਸ ਵਿਕਲਪ ਨੂੰ ਚੈੱਕ ਕਰਕੇ ਰੱਖਣ ਦੀ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ਖੋਜ ਪੜ੍ਹੋ</a> ।','Do not hide "Address line 2" fields behind a link button' => 'ਲਿੰਕ ਬਟਨ ਦੇ ਪਿੱਛੇ &quot;ਐਡਰੈੱਸ ਲਾਈਨ 2&quot; ਖੇਤਰਾਂ ਨੂੰ ਨਾ ਲੁਕਾਓ।','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'ਸਿਰਫ਼ ਉਦੋਂ ਹੀ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਜ਼ਿਆਦਾਤਰ ਗਾਹਕਾਂ ਨੂੰ ਅਸਲ ਵਿੱਚ &quot;ਐਡਰੈੱਸ ਲਾਈਨ 2&quot; ਖੇਤਰ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ, ਜਾਂ ਜਦੋਂ ਸਹੀ ਸ਼ਿਪਿੰਗ ਪਤਾ ਪ੍ਰਾਪਤ ਕਰਨਾ ਬਹੁਤ ਜ਼ਰੂਰੀ ਹੁੰਦਾ ਹੈ (ਭਾਵ, ਜੇਕਰ ਭੋਜਨ ਅਤੇ ਹੋਰ ਨਾਸ਼ਵਾਨ ਉਤਪਾਦਾਂ ਦੀ ਡਿਲੀਵਰੀ ਕੀਤੀ ਜਾ ਰਹੀ ਹੋਵੇ)।','Billing address' => 'ਬਿਲਿੰਗ ਪਤਾ','Select position where to display the billing address section on the checkout page.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਦੀ ਸਥਿਤੀ ਚੁਣੋ।','As a step before shipping' => 'ਸ਼ਿਪਿੰਗ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਕਦਮ ਦੇ ਤੌਰ &#39;ਤੇ','As a sub-step before the shipping address section' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਉਪ-ਕਦਮ ਵਜੋਂ','As a sub-step after the shipping address section' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਤੋਂ ਬਾਅਦ ਇੱਕ ਉਪ-ਕਦਮ ਵਜੋਂ','As a step after shipping' => 'ਸ਼ਿਪਿੰਗ ਤੋਂ ਬਾਅਦ ਇੱਕ ਕਦਮ ਦੇ ਤੌਰ &#39;ਤੇ','As a sub-step before the payment section' => 'ਭੁਗਤਾਨ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਉਪ-ਕਦਮ ਵਜੋਂ','Force billing and shipping addresses to the same (single section)' => 'ਬਿਲਿੰਗ ਅਤੇ ਸ਼ਿਪਿੰਗ ਪਤਿਆਂ ਨੂੰ ਇੱਕੋ (ਸਿੰਗਲ ਸੈਕਸ਼ਨ) &#39;ਤੇ ਜ਼ਬਰਦਸਤੀ ਰੱਖੋ','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;ਸ਼ਿਪਿੰਗ/ਬਿਲਿੰਗ ਪਤੇ ਦੇ ਸਮਾਨ&quot; ਲਈ ਚੈੱਕਬਾਕਸ ਨੂੰ ਪੂਰਵ-ਨਿਰਧਾਰਤ ਤੌਰ &#39;ਤੇ ਚੁਣਿਆ ਗਿਆ ਹੈ','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ਜਦੋਂ ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਪਹਿਲਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ ਤਾਂ &quot;ਸ਼ਿਪਿੰਗ ਪਤੇ ਵਾਂਗ ਹੀ&quot; ਚੈੱਕਬਾਕਸ ਡਿਫੌਲਟ ਤੌਰ &#39;ਤੇ ਚੈੱਕ ਕੀਤਾ ਗਿਆ ਸ਼ੁਰੂ ਹੋ ਜਾਵੇਗਾ।<br> ਜਦੋਂ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਪਹਿਲਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ ਤਾਂ &quot;ਬਿਲਿੰਗ ਪਤੇ ਵਾਂਗ ਹੀ&quot; ਚੈੱਕਬਾਕਸ ਡਿਫੌਲਟ ਤੌਰ &#39;ਤੇ ਨਿਸ਼ਾਨਬੱਧ ਕੀਤਾ ਹੋਇਆ ਸ਼ੁਰੂ ਹੋ ਜਾਵੇਗਾ।<br> ਚੈੱਕਆਉਟ &#39;ਤੇ ਖੁੱਲ੍ਹੇ ਇਨਪੁਟ ਖੇਤਰਾਂ ਦੀ ਗਿਣਤੀ ਨੂੰ ਕਾਫ਼ੀ ਘਟਾਉਣ ਲਈ, ਇਸ ਵਿਕਲਪ ਨੂੰ ਚੈੱਕ ਕੀਤੇ ਛੱਡਣ ਦੀ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ਖੋਜ ਪੜ੍ਹੋ</a> ।','Highlight the billing address section in the checkout form' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਨੂੰ ਉਜਾਗਰ ਕਰੋ।','Shipping address' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ','Highlight the shipping address section in the checkout form' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਨੂੰ ਉਜਾਗਰ ਕਰੋ','Shipping methods' => 'ਸ਼ਿਪਿੰਗ ਦੇ ਤਰੀਕੇ','Choose in which position to display the shipping methods section.' => 'ਚੁਣੋ ਕਿ ਸ਼ਿਪਿੰਗ ਵਿਧੀਆਂ ਵਾਲੇ ਭਾਗ ਨੂੰ ਕਿਸ ਸਥਿਤੀ ਵਿੱਚ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ।','Before shipping address' => 'ਸ਼ਿਪਿੰਗ ਪਤੇ ਤੋਂ ਪਹਿਲਾਂ','After shipping address' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ ਤੋਂ ਬਾਅਦ','Local pickup' => 'ਸਥਾਨਕ ਪਿਕਅੱਪ','Removes shipping address section when a local pickup shipping method is selected.' => 'ਜਦੋਂ ਸਥਾਨਕ ਪਿਕਅੱਪ ਸ਼ਿਪਿੰਗ ਵਿਧੀ ਚੁਣੀ ਜਾਂਦੀ ਹੈ ਤਾਂ ਸ਼ਿਪਿੰਗ ਪਤਾ ਸੈਕਸ਼ਨ ਨੂੰ ਹਟਾ ਦਿੰਦਾ ਹੈ।','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ਜਦੋਂ ਸਥਾਨਕ ਪਿਕਅੱਪ ਸ਼ਿਪਿੰਗ ਵਿਧੀ ਚੁਣੀ ਜਾਂਦੀ ਹੈ ਤਾਂ ਸ਼ਿਪਿੰਗ ਪਤੇ ਨੂੰ ਪਿਕਅੱਪ ਪੁਆਇੰਟ ਸਥਾਨ ਨਾਲ ਬਦਲ ਦਿੰਦਾ ਹੈ।','Choose which address to save as the shipping address for local pickup orders.' => 'ਸਥਾਨਕ ਪਿਕਅੱਪ ਆਰਡਰਾਂ ਲਈ ਸ਼ਿਪਿੰਗ ਪਤੇ ਵਜੋਂ ਕਿਹੜਾ ਪਤਾ ਸੁਰੱਖਿਅਤ ਕਰਨਾ ਹੈ, ਚੁਣੋ।','Save the selected pickup location' => 'ਚੁਣੇ ਹੋਏ ਪਿਕਅੱਪ ਸਥਾਨ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰੋ','Save same as the billing address' => 'ਬਿਲਿੰਗ ਪਤੇ ਵਾਂਗ ਹੀ ਸੇਵ ਕਰੋ','Do not save any shipping address' => 'ਕੋਈ ਵੀ ਸ਼ਿਪਿੰਗ ਪਤਾ ਸੇਵ ਨਾ ਕਰੋ','Company name field for shipping address' => 'ਸ਼ਿਪਿੰਗ ਪਤੇ ਲਈ ਕੰਪਨੀ ਦਾ ਨਾਮ ਖੇਤਰ','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ &#39;ਤੇ ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਲਈ ਕੰਪਨੀ ਦੇ ਨਾਮ ਖੇਤਰ ਦੀ ਦਿੱਖ ਬਦਲੋ।','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ਜੇਕਰ ਖੇਤਰ ਨੂੰ &quot;ਵਿਕਲਪਿਕ&quot; ਵਜੋਂ ਸੈੱਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਜੋ ਕਿ ਡਿਫੌਲਟ ਦ੍ਰਿਸ਼ਟੀ ਸਥਿਤੀ ਹੈ, ਤਾਂ ਕੋਈ ਵੀ ਬਦਲਾਅ ਲਾਗੂ ਨਹੀਂ ਕੀਤਾ ਜਾਵੇਗਾ ਤਾਂ ਜੋ ਹੋਰ ਪਲੱਗਇਨਾਂ ਨੂੰ ਉਹਨਾਂ ਨੂੰ ਲੋੜੀਂਦੇ ਬਦਲਾਅ ਲਾਗੂ ਕਰਨ ਦਿੱਤੇ ਜਾ ਸਕਣ।','Hidden (remove field)' => 'ਲੁਕਿਆ ਹੋਇਆ (ਖੇਤਰ ਹਟਾਓ)','Optional' => 'ਵਿਕਲਪਿਕ','Required' => 'ਲੋੜੀਂਦਾ','Add shipping phone field to the checkout form.' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਸ਼ਿਪਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ।','Choose in which step to display the shipping phone field.' => 'ਚੁਣੋ ਕਿ ਕਿਸ ਪੜਾਅ ਵਿੱਚ ਸ਼ਿਪਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ।','Contact step' => 'ਸੰਪਰਕ ਕਦਮ','Billing phone' => 'ਬਿਲਿੰਗ ਫ਼ੋਨ','Add billing phone field to the checkout form.' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਬਿਲਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ।','Choose in which step to display the billing phone field.' => 'ਚੁਣੋ ਕਿ ਕਿਸ ਪੜਾਅ ਵਿੱਚ ਬਿਲਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ।','Show country code beside the flag' => 'ਝੰਡੇ ਦੇ ਨਾਲ ਦੇਸ਼ ਦਾ ਕੋਡ ਦਿਖਾਓ','Show an example of a valid phone number inside phone fields' => 'ਫ਼ੋਨ ਖੇਤਰਾਂ ਦੇ ਅੰਦਰ ਇੱਕ ਵੈਧ ਫ਼ੋਨ ਨੰਬਰ ਦੀ ਇੱਕ ਉਦਾਹਰਣ ਦਿਖਾਓ','Do not change placeholders' => 'ਪਲੇਸਹੋਲਡਰਾਂ ਨੂੰ ਨਾ ਬਦਲੋ','Show if not defined' => 'ਜੇਕਰ ਪਰਿਭਾਸ਼ਿਤ ਨਹੀਂ ਹੈ ਤਾਂ ਦਿਖਾਓ','Always show' => 'ਹਮੇਸ਼ਾ ਦਿਖਾਓ','Order notes' => 'ਨੋਟਸ ਆਰਡਰ ਕਰੋ','Define the visibility of the additional order notes field.' => 'ਵਾਧੂ ਆਰਡਰ ਨੋਟਸ ਖੇਤਰ ਦੀ ਦਿੱਖ ਨੂੰ ਪਰਿਭਾਸ਼ਿਤ ਕਰੋ।','Gift options' => 'ਤੋਹਫ਼ੇ ਦੇ ਵਿਕਲਪ','Allow customers to add a gift message and other gift related options to the order.' => 'ਗਾਹਕਾਂ ਨੂੰ ਆਰਡਰ ਵਿੱਚ ਤੋਹਫ਼ੇ ਦਾ ਸੁਨੇਹਾ ਅਤੇ ਹੋਰ ਤੋਹਫ਼ੇ ਨਾਲ ਸਬੰਧਤ ਵਿਕਲਪ ਜੋੜਨ ਦੀ ਆਗਿਆ ਦਿਓ।','Display the gift message as part of the order details table instead of a separate section' => 'ਤੋਹਫ਼ੇ ਦੇ ਸੁਨੇਹੇ ਨੂੰ ਵੱਖਰੇ ਭਾਗ ਦੀ ਬਜਾਏ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੀ ਸਾਰਣੀ ਦੇ ਹਿੱਸੇ ਵਜੋਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ਇਹ ਵਿਕਲਪ ਆਰਡਰ ਪੁਸ਼ਟੀਕਰਨ ਪੰਨੇ (ਧੰਨਵਾਦ ਪੰਨਾ) ਅਤੇ ਖਾਤਾ ਪੰਨਿਆਂ, ਈਮੇਲਾਂ ਅਤੇ ਪੈਕਿੰਗ ਸਲਿੱਪਾਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ।','Account matching' => 'ਖਾਤਾ ਮਿਲਾਨ','Enable the account matching feature' => 'ਖਾਤਾ ਮਿਲਾਨ ਵਿਸ਼ੇਸ਼ਤਾ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ਜਦੋਂ ਗਾਹਕ ਦੇ ਸੰਪਰਕ ਵੇਰਵਿਆਂ ਵਾਲਾ ਖਾਤਾ ਪਹਿਲਾਂ ਹੀ ਮੌਜੂਦ ਹੋਵੇ ਤਾਂ ਮਹਿਮਾਨ ਗਾਹਕ ਦੇ ਆਰਡਰਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਮੌਜੂਦਾ ਖਾਤੇ ਨਾਲ ਜੋੜੋ।','Display message when an account exists with the email address provided' => 'ਜਦੋਂ ਦਿੱਤੇ ਗਏ ਈਮੇਲ ਪਤੇ ਨਾਲ ਕੋਈ ਖਾਤਾ ਮੌਜੂਦ ਹੋਵੇ ਤਾਂ ਸੁਨੇਹਾ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'ਖਾਤਾ ਬਣਾਉਣ ਵਾਲੇ ਖੇਤਰਾਂ ਨੂੰ ਇੱਕ ਸੂਚਨਾ ਅਤੇ ਲੌਗਇਨ ਕਰਨ ਦੇ ਵਿਕਲਪ ਨਾਲ ਬਦਲਦਾ ਹੈ। ਕੁਝ ਸੰਦਰਭਾਂ ਵਿੱਚ, ਗਾਹਕਾਂ ਦੀ ਗੋਪਨੀਯਤਾ ਦੀ ਰੱਖਿਆ ਲਈ ਇਸ ਵਿਕਲਪ ਨੂੰ ਅਯੋਗ ਛੱਡਣ ਦੀ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ।','Dashboard' => 'ਡੈਸ਼ਬੋਰਡ','Integrations' => 'ਏਕੀਕਰਨ','License keys' => 'ਲਾਇਸੈਂਸ ਕੁੰਜੀਆਂ','Visit our website for more information about our plugins and add-ons.' => 'ਸਾਡੇ ਪਲੱਗਇਨ ਅਤੇ ਐਡ-ਆਨ ਬਾਰੇ ਹੋਰ ਜਾਣਕਾਰੀ ਲਈ ਸਾਡੀ ਵੈੱਬਸਾਈਟ &#39;ਤੇ ਜਾਓ।','Order pay page' => 'ਆਰਡਰ ਭੁਗਤਾਨ ਪੰਨਾ','Order pay' => 'ਆਰਡਰ ਪੇ','Enable order pay page optimizations' => 'ਆਰਡਰ ਪੇਅ ਪੇਜ ਅਨੁਕੂਲਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ਗਾਹਕ ਤੋਂ ਬਕਾਇਆ ਭੁਗਤਾਨ ਵਾਲੇ ਮੌਜੂਦਾ ਆਰਡਰਾਂ ਲਈ ਆਰਡਰ ਪੇ ਪੇਜ ਦਾ ਲੇਆਉਟ ਬਦਲਦਾ ਹੈ।','Add widget areas to the order pay page' => 'ਆਰਡਰ ਪੇਅ ਪੇਜ &#39;ਤੇ ਵਿਜੇਟ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ਇਹਨਾਂ ਵਿਜੇਟ ਖੇਤਰਾਂ ਦੀ ਵਰਤੋਂ ਆਰਡਰ ਪੇਅ ਪੇਜ &#39;ਤੇ ਟਰੱਸਟ ਸਿੰਬਲ ਅਤੇ ਟਰੱਸਟ ਬੈਜ ਜੋੜਨ ਲਈ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।','Thank you page & order details layout' => 'ਧੰਨਵਾਦ ਪੰਨਾ ਅਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦਾ ਲੇਆਉਟ','Order details optimizations' => 'ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੇ ਅਨੁਕੂਲਨ','Enable thank you page and order details optimizations' => 'ਧੰਨਵਾਦ ਪੰਨੇ ਅਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੇ ਅਨੁਕੂਲਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Changes the layout of order details on the thank you page and account pages.' => 'ਧੰਨਵਾਦ ਪੰਨੇ ਅਤੇ ਖਾਤਾ ਪੰਨਿਆਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦਾ ਖਾਕਾ ਬਦਲਦਾ ਹੈ।','Enable order details customizations on email notifications' => 'ਈਮੇਲ ਸੂਚਨਾਵਾਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੇ ਅਨੁਕੂਲਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ਈਮੇਲ ਸੂਚਨਾਵਾਂ &#39;ਤੇ ਨਵੇਂ ਭਾਗ ਦਿਖਾਓ ਅਤੇ ਭਾਗਾਂ ਦਾ ਕ੍ਰਮ ਬਦਲੋ। ਈਮੇਲ ਸੂਚਨਾਵਾਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੀਆਂ ਸ਼ੈਲੀਆਂ ਵਿੱਚ ਕੋਈ ਬਦਲਾਅ ਨਹੀਂ ਹੈ।','Thank you page' => 'ਧੰਨਵਾਦ ਪੰਨਾ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ਇਹ ਵਿਕਲਪ ਧੰਨਵਾਦ ਪੰਨੇ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ, ਜਿਸਨੂੰ ਆਰਡਰ ਪ੍ਰਾਪਤ ਜਾਂ ਆਰਡਰ ਪੁਸ਼ਟੀਕਰਨ ਪੰਨੇ ਵੀ ਕਿਹਾ ਜਾਂਦਾ ਹੈ।','Order details layout' => 'ਆਰਡਰ ਵੇਰਵਿਆਂ ਦਾ ਖਾਕਾ','Display the order details with wide layout on the thank you page' => 'ਧੰਨਵਾਦ ਪੰਨੇ &#39;ਤੇ ਚੌੜੇ ਲੇਆਉਟ ਦੇ ਨਾਲ ਆਰਡਰ ਵੇਰਵੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','Add widget areas to the thank you page' => 'ਧੰਨਵਾਦ ਪੰਨੇ &#39;ਤੇ ਵਿਜੇਟ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'ਇਹਨਾਂ ਵਿਜੇਟ ਖੇਤਰਾਂ ਦੀ ਵਰਤੋਂ ਧੰਨਵਾਦ ਪੰਨੇ &#39;ਤੇ ਵਿਸ਼ਵਾਸ ਚਿੰਨ੍ਹ ਅਤੇ ਵਿਸ਼ਵਾਸ ਬੈਜ ਜੋੜਨ ਲਈ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।','Order actions' => 'ਕਾਰਵਾਈਆਂ ਦਾ ਆਰਡਰ ਦਿਓ','Choose in which position to display the order actions.' => 'ਚੁਣੋ ਕਿ ਆਰਡਰ ਕਾਰਵਾਈਆਂ ਨੂੰ ਕਿਸ ਸਥਿਤੀ ਵਿੱਚ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ।','Inside the order overview' => 'ਆਰਡਰ ਸੰਖੇਪ ਜਾਣਕਾਰੀ ਦੇ ਅੰਦਰ','After the order overview' => 'ਆਰਡਰ ਸੰਖੇਪ ਜਾਣਕਾਰੀ ਤੋਂ ਬਾਅਦ','After order sections' => 'ਆਰਡਰ ਸੈਕਸ਼ਨਾਂ ਤੋਂ ਬਾਅਦ','Order status' => 'ਆਰਡਰ ਸਥਿਤੀ','Display the order status progress bar' => 'ਆਰਡਰ ਸਥਿਤੀ ਪ੍ਰਗਤੀ ਪੱਟੀ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Choose in which position to display the section.' => 'ਚੁਣੋ ਕਿ ਭਾਗ ਨੂੰ ਕਿਸ ਸਥਿਤੀ ਵਿੱਚ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ।','After the order overview and payment instructions' => 'ਆਰਡਰ ਸੰਖੇਪ ਜਾਣਕਾਰੀ ਅਤੇ ਭੁਗਤਾਨ ਨਿਰਦੇਸ਼ਾਂ ਤੋਂ ਬਾਅਦ','Before the order items section' => 'ਆਰਡਰ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ','Inside the order items section' => 'ਆਰਡਰ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਦੇ ਅੰਦਰ','After the order items section' => 'ਆਰਡਰ ਆਈਟਮਾਂ ਵਾਲੇ ਭਾਗ ਤੋਂ ਬਾਅਦ','On the sidebar' => 'ਸਾਈਡਬਾਰ &#39;ਤੇ','Order downloads' => 'ਡਾਊਨਲੋਡ ਆਰਡਰ ਕਰੋ','Gift message' => 'ਤੋਹਫ਼ੇ ਦਾ ਸੁਨੇਹਾ','Tools' => 'ਔਜ਼ਾਰ','Troubleshooting' => 'ਸਮੱਸਿਆ ਨਿਵਾਰਣ','Debug options' => 'ਡੀਬੱਗ ਵਿਕਲਪ','Debug mode' => 'ਡੀਬੱਗ ਮੋਡ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ਡੀਬੱਗ ਮੋਡ ਦੀ ਵਰਤੋਂ ਵੈੱਬਸਾਈਟ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ। ਇਸ ਵਿਕਲਪ ਦੀ ਵਰਤੋਂ ਸਿਰਫ਼ ਸਮੱਸਿਆ ਨਿਪਟਾਰਾ ਕਰਦੇ ਸਮੇਂ ਕਰੋ।','Load unminified assets' => 'ਅਣ-ਨਿਰਧਾਰਤ ਸੰਪਤੀਆਂ ਲੋਡ ਕਰੋ','Enhanced select fields' => 'ਵਧੇ ਹੋਏ ਚੋਣਵੇਂ ਖੇਤਰ','Fix automatic zoom-in on form fields' => 'ਫਾਰਮ ਖੇਤਰਾਂ &#39;ਤੇ ਆਟੋਮੈਟਿਕ ਜ਼ੂਮ-ਇਨ ਠੀਕ ਕਰੋ','Set <code>font-size</code> inside form fields to 16px' => 'ਫਾਰਮ ਫੀਲਡਾਂ ਦੇ ਅੰਦਰ <code>font-size</code> 16px ਤੇ ਸੈੱਟ ਕਰੋ','Fluid Checkout' => 'ਤਰਲ ਪਦਾਰਥਾਂ ਦੀ ਜਾਂਚ','Settings' => 'ਸੈਟਿੰਗਾਂ','Support' => 'ਸਹਿਯੋਗ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'ਹੋਰ ਵਿਕਲਪਾਂ ਨੂੰ ਅਨਲੌਕ ਕਰਨ ਲਈ <a target="_blank" href="%s">PRO ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ</a> ।','(PRO)' => '(ਪ੍ਰੋ)','(experimental)' => '(ਪ੍ਰਯੋਗਾਤਮਕ)','Please verify your phone number.' => 'ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੇ ਫ਼ੋਨ ਨੰਬਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।','The Bluehost Plugin' => 'ਬਲੂਹੋਸਟ ਪਲੱਗਇਨ','Custom fields' => 'ਕਸਟਮ ਖੇਤਰ','Enable custom shipping email field' => 'ਵਿਉਂਤਬੱਧ ਸ਼ਿਪਿੰਗ ਈਮੇਲ ਖੇਤਰ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ਜਦੋਂ ਸਮਰੱਥ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਬਲੂਹੋਸਟ ਪਲੱਗਇਨ ਤੋਂ ਸ਼ਿਪਿੰਗ ਈਮੇਲ ਖੇਤਰ ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਜੋੜਿਆ ਜਾਵੇਗਾ।','Captcha Pro by BestWebSoft' => 'ਬੈਸਟਵੈੱਬਸਾਫਟ ਦੁਆਰਾ ਕੈਪਚਾ ਪ੍ਰੋ','Captcha position' => 'ਕੈਪਚਾ ਸਥਿਤੀ','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'ਕੈਪਚਾ ਭਾਗ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਸਥਿਤੀ ਪਰਿਭਾਸ਼ਿਤ ਕਰੋ। ਚੁਣੇ ਗਏ ਕੈਪਚਾ ਕਿਸਮ ਦੇ ਆਧਾਰ &#39;ਤੇ ਕੁਝ ਸਥਿਤੀਆਂ ਕੰਮ ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ।','Selecting a pickup point is required before proceeding.' => 'ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਪਿਕਅੱਪ ਪੁਆਇੰਟ ਚੁਣਨਾ ਜ਼ਰੂਰੀ ਹੈ।','Pickup point' => 'ਪਿਕਅੱਪ ਪੁਆਇੰਟ','Pickup point not selected yet.' => 'ਪਿਕਅੱਪ ਪੁਆਇੰਟ ਅਜੇ ਚੁਣਿਆ ਨਹੀਂ ਗਿਆ।','Pickup point:' => 'ਪਿਕਅੱਪ ਪੁਆਇੰਟ:','Mailchimp for WooCommerce' => 'WooCommerce ਲਈ ਮੇਲਚਿੰਪ','Subscribe checkbox' => 'ਗਾਹਕ ਬਣੋ ਚੈੱਕਬਾਕਸ','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਗਾਹਕੀ ਚੈੱਕਬਾਕਸ ਦੀ ਸਥਿਤੀ ਨੂੰ ਓਵਰਰਾਈਡ ਕਰੋ ਅਤੇ ਇਸਨੂੰ ਹਮੇਸ਼ਾ ਸੰਪਰਕ ਪੜਾਅ &#39;ਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','Before Shipping Address' => 'ਭੇਜਣ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਪਤਾ','(originally "%s")' => '(ਮੂਲ ਰੂਪ ਵਿੱਚ &quot;%s&quot;)','After Shipping Address' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ ਤੋਂ ਬਾਅਦ','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPoint ਨਾਲ ਸ਼ਿਪਿੰਗ ਕਰਦੇ ਸਮੇਂ ਇੱਕ ਕਲੈਕਸ਼ਨ ਪੁਆਇੰਟ ਚੁਣਨਾ ਜ਼ਰੂਰੀ ਹੈ।','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ਜੇਕਰ ਚੈੱਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਤਾਂ ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਈਮੇਲ ਵਿੱਚ ਗਲਤੀਆਂ ਦੀ ਸੂਚਨਾ ਦਿੰਦਾ ਹੈ। (ਇਹ ਵਿਸ਼ੇਸ਼ਤਾ ਬੰਦ ਕਰ ਦਿੱਤੀ ਗਈ ਹੈ ਕਿਉਂਕਿ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਇਹ ਵਿਸ਼ੇਸ਼ਤਾ ਪੇਸ਼ ਕਰਦਾ ਹੈ। ਇਸ ਵਿਕਲਪ ਵਿੱਚ ਬਦਲਾਅ ਲਾਗੂ ਨਹੀਂ ਹੋਣਗੇ)','Enable Mail Check: (disabled feature)' => 'ਮੇਲ ਚੈੱਕ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ: (ਅਯੋਗ ਵਿਸ਼ੇਸ਼ਤਾ)','Carrier:' => 'ਕੈਰੀਅਰ:','Sendinblue - WooCommerce Email Marketing' => 'ਸੇਂਡਿਨਬਲੂ - ਵੂਕਾਮਰਸ ਈਮੇਲ ਮਾਰਕੀਟਿੰਗ','Sign up checkbox position' => 'ਸਾਈਨ ਅੱਪ ਚੈੱਕਬਾਕਸ ਸਥਿਤੀ','Move the sign up checkbox to the contact step' => 'ਸਾਈਨ ਅੱਪ ਚੈੱਕਬਾਕਸ ਨੂੰ ਸੰਪਰਕ ਪੜਾਅ &#39;ਤੇ ਲੈ ਜਾਓ','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ਜਦੋਂ ਸਮਰੱਥ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਚੈੱਕਬਾਕਸ ਨੂੰ ਸੇਂਡਿਨਬਲੂ ਪਲੱਗਇਨ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਪਰਿਭਾਸ਼ਿਤ ਡਿਸਪਲੇ ਸਥਾਨ ਤੋਂ ਸੁਤੰਤਰ ਤੌਰ &#39;ਤੇ ਸੰਪਰਕ ਪੜਾਅ &#39;ਤੇ ਭੇਜਿਆ ਜਾਵੇਗਾ।','Theme Betheme' => 'ਥੀਮ ਬੈਥਮ','Checkout progress' => 'ਚੈੱਕਆਉਟ ਪ੍ਰਗਤੀ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ਬੈਥਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਚੈੱਕਆਉਟ, ਕਾਰਟ ਅਤੇ ਆਰਡਰ ਪ੍ਰਾਪਤ ਪੰਨਿਆਂ &#39;ਤੇ ਆਉਟਪੁੱਟ ਕਰੋ।','Theme Fennik' => 'ਥੀਮ ਫੈਨਿਕ','Breadcrumbs' => 'ਬਰੈੱਡਕ੍ਰੰਬਸ','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਫੈਨਿਕ ਥੀਮ ਤੋਂ ਬ੍ਰੈੱਡਕ੍ਰੰਬਸ ਸੈਕਸ਼ਨ ਨੂੰ ਆਉਟਪੁੱਟ ਦਿਓ।','Theme Go' => 'ਥੀਮ ਗੋ','My account layout' => 'ਮੇਰਾ ਖਾਤਾ ਖਾਕਾ','Enable wide layout on "My account" page.' => '&quot;ਮੇਰਾ ਖਾਤਾ&quot; ਪੰਨੇ &#39;ਤੇ ਚੌੜਾ ਲੇਆਉਟ ਸਮਰੱਥ ਬਣਾਓ।','Theme Impreza' => 'ਥੀਮ ਇਮਪ੍ਰੇਜ਼ਾ','Header' => 'ਸਿਰਲੇਖ','Spacing for site header at the checkout page (in pixels)' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਸਾਈਟ ਹੈੱਡਰ ਲਈ ਸਪੇਸਿੰਗ (ਪਿਕਸਲ ਵਿੱਚ)','Only applicable when using the Impreza theme header at the checkout page.' => 'ਸਿਰਫ਼ ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ Impreza ਥੀਮ ਹੈੱਡਰ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','Theme Kapee' => 'ਥੀਮ ਕਾਪੀ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ਚੈੱਕਆਉਟ, ਕਾਰਟ ਅਤੇ ਆਰਡਰ ਪ੍ਰਾਪਤ ਪੰਨਿਆਂ &#39;ਤੇ ਕੈਪੀ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਆਉਟਪੁੱਟ ਕਰੋ।','Theme Porto' => 'ਥੀਮ ਪੋਰਟੋ','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ਚੈੱਕਆਉਟ, ਕਾਰਟ ਅਤੇ ਆਰਡਰ ਪ੍ਰਾਪਤ ਪੰਨਿਆਂ &#39;ਤੇ ਪੋਰਟੋ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਆਉਟਪੁੱਟ ਕਰੋ।','Theme Pressmart' => 'ਥੀਮ ਪ੍ਰੈਸਮਾਰਟ','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ਪ੍ਰੈਸਮਾਰਟ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਚੈੱਕਆਉਟ, ਕਾਰਟ ਅਤੇ ਆਰਡਰ ਪ੍ਰਾਪਤ ਪੰਨਿਆਂ &#39;ਤੇ ਆਉਟਪੁੱਟ ਕਰੋ।','Theme The Gem' => 'ਥੀਮ ਦ ਹੀਰਾ','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਦ ਜੇਮ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਆਉਟਪੁੱਟ ਦਿਓ।','Theme Woodmart' => 'ਥੀਮ ਵੁੱਡਮਾਰਟ','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਹੈੱਡਰ ਅਤੇ ਫੁੱਟਰ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਵੁੱਡਮਾਰਟ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਆਉਟਪੁੱਟ ਦਿਓ।','Checkout options' => 'ਚੈੱਕਆਉਟ ਵਿਕਲਪ','Disable the theme checkout options' => 'ਥੀਮ ਚੈੱਕਆਉਟ ਵਿਕਲਪਾਂ ਨੂੰ ਅਯੋਗ ਕਰੋ','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ਥੀਮ ਦੁਆਰਾ ਜੋੜੇ ਗਏ ਉਤਪਾਦ ਚਿੱਤਰ, ਮਾਤਰਾ ਖੇਤਰ, ਹਟਾਉਣ ਬਟਨ ਅਤੇ ਉਤਪਾਦ ਪੰਨੇ ਦੇ ਲਿੰਕ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਵਾਲੇ ਵਿਕਲਪ ਡਿਫੌਲਟ ਰੂਪ ਵਿੱਚ ਅਯੋਗ ਹਨ।','Theme Atomion' => 'ਥੀਮ ਐਟੋਮੀਅਨ','Order progress' => 'ਆਰਡਰ ਦੀ ਪ੍ਰਗਤੀ','Display order progress from the theme' => 'ਥੀਮ ਤੋਂ ਆਰਡਰ ਪ੍ਰਗਤੀ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Display the form field labels visible on the page' => 'ਪੰਨੇ &#39;ਤੇ ਦਿਖਾਈ ਦੇਣ ਵਾਲੇ ਫਾਰਮ ਫੀਲਡ ਲੇਬਲ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ।','It is recommended to keep this option enabled for a better user experience.' => 'ਬਿਹਤਰ ਉਪਭੋਗਤਾ ਅਨੁਭਵ ਲਈ ਇਸ ਵਿਕਲਪ ਨੂੰ ਸਮਰੱਥ ਰੱਖਣ ਦੀ ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।','Theme ZK Nito' => 'ਥੀਮ ZK ਨੀਟੋ','Add extra fields to the checkout form' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ ਵਿੱਚ ਵਾਧੂ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਵਿੱਚ ਇੱਕ ਵਾਧੂ ਸ਼ਿਪਿੰਗ ਈਮੇਲ ਅਤੇ ਸ਼ਿਪਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਜੋੜਦਾ ਹੈ।','Go to the home page' => 'ਹੋਮ ਪੇਜ &#39;ਤੇ ਜਾਓ।','Skip to content' => 'ਸਮੱਗਰੀ &#39;ਤੇ ਜਾਓ','Create an account' => 'ਅਕਾਉਂਟ ਬਣਾਓ','Log in to your account' => 'ਆਪਣੇ ਖਾਤੇ ਵਿੱਚ ਲੌਗਇਨ ਕਰੋ','Already have an account?' => 'ਕੀ ਪਹਿਲਾਂ ਤੋਂ ਹੀ ਕੋਈ ਖਾਤਾ ਹੈ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s ਵਜੋਂ ਲੌਗਇਨ ਕੀਤਾ। <a href="%2$s">ਲੌਗ ਆਊਟ ਕਰੋ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'ਤੁਹਾਡੇ ਆਰਡਰ ਦੀ ਕੁੱਲ ਰਕਮ %s ਹੈ। ਹੋਰ ਕਿਸੇ ਭੁਗਤਾਨ ਦੀ ਲੋੜ ਨਹੀਂ ਹੈ।','Close and continue with checkout' => 'ਬੰਦ ਕਰੋ ਅਤੇ ਚੈੱਕਆਉਟ ਜਾਰੀ ਰੱਖੋ','Continue' => 'ਜਾਰੀ ਰੱਖੋ','Parcel terminal' => 'ਪਾਰਸਲ ਟਰਮੀਨਲ','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ਇਸ ਵਿਜੇਟ ਨੂੰ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨਾਲ ਬਦਲ ਦਿੱਤਾ ਗਿਆ ਹੈ।</p><p> ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ, ਚੈੱਕਆਉਟ ਪੰਨੇ ਨੂੰ ਸਹੀ ਢੰਗ ਨਾਲ ਕੰਮ ਕਰਨ ਲਈ ਅਸਲ WooCommerce ਸ਼ਾਰਟਕੋਡ <code>[woocommerce_checkout]</code> ਦੀ ਵਰਤੋਂ ਕਰਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।</p><p> ਹੋਰ ਜਾਣਕਾਰੀ ਲਈ, ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦਸਤਾਵੇਜ਼ ਵੇਖੋ।</p>','Theme The7' => 'ਥੀਮ The7','Additional header sections' => 'ਵਾਧੂ ਸਿਰਲੇਖ ਭਾਗ','Output additional header sections if enabled in the theme settings.' => 'ਜੇਕਰ ਥੀਮ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਮਰੱਥ ਹੋਵੇ ਤਾਂ ਵਾਧੂ ਹੈਡਰ ਭਾਗ ਆਉਟਪੁੱਟ ਕਰੋ।','More information' => 'ਹੋਰ ਜਾਣਕਾਰੀ','Pick a Locker' => 'ਇੱਕ ਲਾਕਰ ਚੁਣੋ','Page template' => 'ਪੰਨਾ ਟੈਮਪਲੇਟ','Use `Order confirmation` page template for block-based themes' => 'ਬਲਾਕ-ਅਧਾਰਿਤ ਥੀਮਾਂ ਲਈ `ਆਰਡਰ ਪੁਸ਼ਟੀਕਰਨ` ਪੰਨਾ ਟੈਂਪਲੇਟ ਦੀ ਵਰਤੋਂ ਕਰੋ।','Only applies when using a block-based theme.' => 'ਸਿਰਫ਼ ਬਲਾਕ-ਅਧਾਰਿਤ ਥੀਮ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','WooCommerce Stripe Gateway' => 'WooCommerce ਸਟ੍ਰਾਈਪ ਗੇਟਵੇ','Payment form' => 'ਭੁਗਤਾਨ ਫਾਰਮ','Apply styles to the Stripe payment form fields' => 'ਸਟ੍ਰਾਈਪ ਭੁਗਤਾਨ ਫਾਰਮ ਖੇਤਰਾਂ ਵਿੱਚ ਸਟਾਈਲ ਲਾਗੂ ਕਰੋ','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ਜਦੋਂ ਸਮਰੱਥ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਪਲੱਗਇਨ ਨਾਲ ਅਨੁਕੂਲਤਾ ਲਈ ਅਨੁਕੂਲਿਤ ਸਟਾਈਲ ਲਾਗੂ ਕਰੇਗਾ। ਜੇਕਰ ਤੁਸੀਂ ਸਟ੍ਰਾਈਪ ਭੁਗਤਾਨ ਫਾਰਮ ਖੇਤਰਾਂ ਲਈ ਕਸਟਮ ਸਟਾਈਲ ਵਰਤ ਰਹੇ ਹੋ ਤਾਂ ਤੁਸੀਂ ਇਸਨੂੰ ਅਯੋਗ ਕਰ ਸਕਦੇ ਹੋ।','Theme Nyture' => 'ਥੀਮ ਨਿਊਚਰ','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ Nyture ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਆਉਟਪੁੱਟ ਦਿਓ।','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ਗਾਹਕਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਆਰਡਰਾਂ ਲਈ ਭੁਗਤਾਨ ਕਰਨ ਦੀ ਆਗਿਆ ਦਿੰਦਾ ਹੈ ਜੋ ਜਾਂ ਤਾਂ ਸਟੋਰ ਐਡਮਿਨ ਦੁਆਰਾ ਹੱਥੀਂ ਬਣਾਏ ਜਾਂਦੇ ਹਨ ਜਾਂ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਪੂਰੇ ਨਹੀਂ ਹੁੰਦੇ।','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers ਦੁਆਰਾ WooCommerce Checkout Manager ਪਲੱਗਇਨ Fluid Checkout ਦੇ ਅਨੁਕੂਲ ਨਹੀਂ ਹੈ।','Company name field for billing address' => 'ਬਿਲਿੰਗ ਪਤੇ ਲਈ ਕੰਪਨੀ ਦਾ ਨਾਮ ਖੇਤਰ','Change visibility for the company name field for the billing address section on the checkout form.' => 'ਚੈੱਕਆਉਟ ਫਾਰਮ &#39;ਤੇ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਲਈ ਕੰਪਨੀ ਦੇ ਨਾਮ ਖੇਤਰ ਦੀ ਦਿੱਖ ਬਦਲੋ।','Theme Bookshelf' => 'ਥੀਮ ਬੁੱਕ ਸ਼ੈਲਫ','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਬੁੱਕਸ਼ੈਲਫ ਥੀਮ ਤੋਂ ਚੈੱਕਆਉਟ ਸਟੈਪਸ ਸੈਕਸ਼ਨ ਨੂੰ ਆਉਟਪੁੱਟ ਦਿਓ।','Account password' => 'ਖਾਤੇ ਦਾ ਪਾਸਵਰਡ','An account will be created with the information provided at checkout when completing the order.' => 'ਆਰਡਰ ਪੂਰਾ ਕਰਦੇ ਸਮੇਂ ਚੈੱਕਆਉਟ &#39;ਤੇ ਦਿੱਤੀ ਗਈ ਜਾਣਕਾਰੀ ਨਾਲ ਇੱਕ ਖਾਤਾ ਬਣਾਇਆ ਜਾਵੇਗਾ।','Choose the style of the progress bar.' => 'ਤਰੱਕੀ ਪੱਟੀ ਦੀ ਸ਼ੈਲੀ ਚੁਣੋ।','Bars' => 'ਬਾਰ','Theme Ireca' => 'ਥੀਮ ਇਰੇਕਾ','WooCommerce page layout' => 'WooCommerce ਪੰਨਾ ਲੇਆਉਟ','Force wide layout on WooCommerce pages' => 'WooCommerce ਪੰਨਿਆਂ &#39;ਤੇ ਚੌੜਾ ਲੇਆਉਟ ਮਜਬੂਰ ਕਰੋ','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦਾ ਹੈ ਕਿ WooCommerce ਪੰਨਿਆਂ &#39;ਤੇ ਸਮੱਗਰੀ ਭਾਗ ਬਹੁਤ ਤੰਗ ਨਾ ਹੋਵੇ ਜਿਸ ਵਿੱਚ ਚੈੱਕਆਉਟ, ਕਾਰਟ, ਆਰਡਰ ਪ੍ਰਾਪਤ, ਆਰਡਰ ਭੁਗਤਾਨ ਅਤੇ ਖਾਤਾ ਪੰਨੇ ਸ਼ਾਮਲ ਹਨ।','WooCommerce Smart Coupons' => 'WooCommerce ਸਮਾਰਟ ਕੂਪਨ','Position on checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਸਥਿਤੀ','Choose where to display the available coupons section on the checkout page.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਉਪਲਬਧ ਕੂਪਨ ਭਾਗ ਨੂੰ ਕਿੱਥੇ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨਾ ਹੈ, ਚੁਣੋ।','Before the progress bar' => 'ਤਰੱਕੀ ਪੱਟੀ ਤੋਂ ਪਹਿਲਾਂ','After the progress bar' => 'ਤਰੱਕੀ ਪੱਟੀ ਤੋਂ ਬਾਅਦ','Before coupon codes section' => 'ਕੂਪਨ ਕੋਡ ਸੈਕਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ','Format phone numbers according to the rules for each country.' => 'ਹਰੇਕ ਦੇਸ਼ ਦੇ ਨਿਯਮਾਂ ਅਨੁਸਾਰ ਫ਼ੋਨ ਨੰਬਰਾਂ ਨੂੰ ਫਾਰਮੈਟ ਕਰੋ।','Use precise phone number validation' => 'ਸਟੀਕ ਫ਼ੋਨ ਨੰਬਰ ਪ੍ਰਮਾਣਿਕਤਾ ਦੀ ਵਰਤੋਂ ਕਰੋ','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ਇਹ ਇੱਕ ਪ੍ਰਯੋਗਾਤਮਕ ਵਿਸ਼ੇਸ਼ਤਾ ਹੈ ਅਤੇ ਹੋ ਸਕਦਾ ਹੈ ਕਿ ਸਾਰੇ ਸੈੱਟਅੱਪਾਂ ਵਿੱਚ ਉਮੀਦ ਅਨੁਸਾਰ ਕੰਮ ਨਾ ਕਰੇ। ਇਸਨੂੰ ਸਾਵਧਾਨੀ ਨਾਲ ਵਰਤੋ।','Phone number validation types used when precise validation is enabled.' => 'ਜਦੋਂ ਸਟੀਕ ਪ੍ਰਮਾਣਿਕਤਾ ਚਾਲੂ ਹੁੰਦੀ ਹੈ ਤਾਂ ਫ਼ੋਨ ਨੰਬਰ ਪ੍ਰਮਾਣਿਕਤਾ ਕਿਸਮਾਂ ਵਰਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।','Mobile' => 'ਮੋਬਾਈਲ','Fixed line' => 'ਸਥਿਰ ਲਾਈਨ','Toll free' => 'ਟੋਲ ਫ੍ਰੀ','Or' => 'ਜਾਂ','Contact' => 'ਸੰਪਰਕ','Multi step' => 'ਮਲਟੀ ਸਟੈਪ','2 columns' => '2 ਕਾਲਮ','1 column' => '1 ਕਾਲਮ','Before checkout steps' => 'ਚੈੱਕਆਉਟ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਪੜਾਅ','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 ਕਾਲਮ&quot;</em> ਚੈੱਕਆਉਟ ਲੇਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਇਹ ਵਿਕਲਪ ਹਮੇਸ਼ਾਂ <em>&quot;ਚੈਕਆਉਟ ਕਦਮਾਂ ਤੋਂ ਪਹਿਲਾਂ&quot;</em> ਤੇ ਸੈੱਟ ਹੁੰਦਾ ਹੈ ਅਤੇ ਡੈਸਕਟੌਪ ਦ੍ਰਿਸ਼ ਤੇ ਵੀ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','Position for the extra order summary section on mobile.' => 'ਮੋਬਾਈਲ &#39;ਤੇ ਵਾਧੂ ਆਰਡਰ ਸੰਖੇਪ ਭਾਗ ਲਈ ਸਥਿਤੀ।','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;ਸਾਈਟ ਹੈੱਡਰ &#39;ਤੇ&quot;</em> ਵਿਕਲਪ ਸਿਰਫ਼ ਭਟਕਣਾ-ਮੁਕਤ ਹੈੱਡਰ ਦੀ ਵਰਤੋਂ ਕਰਨ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','On the site header (requires distraction-free header)' => 'ਸਾਈਟ ਹੈੱਡਰ &#39;ਤੇ (ਭਟਕਣਾ-ਮੁਕਤ ਹੈੱਡਰ ਦੀ ਲੋੜ ਹੈ)','Initial state for the expansible order summary section on mobile.' => 'ਮੋਬਾਈਲ &#39;ਤੇ ਵਿਸਤ੍ਰਿਤ ਆਰਡਰ ਸੰਖੇਪ ਭਾਗ ਲਈ ਸ਼ੁਰੂਆਤੀ ਸਥਿਤੀ।','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'ਅਸੀਂ ਰੈਗੂਲੇਟਰੀ ਜ਼ਰੂਰਤਾਂ ਦੇ ਕਾਰਨ ਇਸਨੂੰ ਹੇਠ ਲਿਖੇ ਦੇਸ਼ਾਂ ਲਈ <em>ਵਿਸਤ੍ਰਿਤ</em> ਵਜੋਂ ਸੈੱਟ ਕਰਨ ਦੀ ਸਿਫਾਰਸ਼ ਕਰਦੇ ਹਾਂ: <strong>ਜਰਮਨੀ</strong> , <strong>ਆਸਟਰੀਆ</strong> , <strong>ਸਵਿਟਜ਼ਰਲੈਂਡ</strong> , <strong>ਨੀਦਰਲੈਂਡ</strong> , <strong>ਪੋਲੈਂਡ</strong> , <strong>ਬੈਲਜੀਅਮ</strong> ਅਤੇ <strong>ਫਰਾਂਸ</strong> ।','Collapsed' => 'ਸਮੇਟਿਆ ਗਿਆ','Expanded' => 'ਫੈਲਾਇਆ ਗਿਆ','Do not show' => 'ਨਾ ਦਿਖਾਓ','yes' => 'ਹਾਂ','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ਜੇਕਰ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਤੋਂ ਬਾਅਦ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਸ਼ਿਪਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਨੂੰ &quot;ਲੋੜੀਂਦਾ&quot; ਵਜੋਂ ਮਜਬੂਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ, ਅਤੇ ਬਿਲਿੰਗ ਫ਼ੋਨ ਖੇਤਰ &quot;ਲੋੜੀਂਦਾ&quot; ਵਜੋਂ ਸੈੱਟ ਕੀਤਾ ਗਿਆ ਹੈ। ਇਹ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਜ਼ਰੂਰੀ ਹੈ ਕਿ ਸ਼ਿਪਿੰਗ ਪਤੇ ਨੂੰ ਬਿਲਿੰਗ ਪਤੇ &#39;ਤੇ ਕਾਪੀ ਕੀਤਾ ਜਾ ਸਕੇ ਜਦੋਂ ਉਸ ਵਿਕਲਪ ਦੀ ਜਾਂਚ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਨਹੀਂ ਤਾਂ ਗਾਹਕ ਚੈੱਕਆਉਟ ਫਾਰਮ ਨੂੰ ਪੂਰਾ ਕਰਨ ਦੇ ਯੋਗ ਨਹੀਂ ਹੋ ਸਕਦਾ।','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ਜੇਕਰ ਬਿਲਿੰਗ ਪਤਾ ਭਾਗ ਸ਼ਿਪਿੰਗ ਪਤਾ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਸ਼ਿਪਿੰਗ ਫੋਨ ਖੇਤਰ &quot;ਲੋੜੀਂਦਾ&quot; ਵਜੋਂ ਸੈੱਟ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਬਿਲਿੰਗ ਫ਼ੋਨ ਖੇਤਰ ਨੂੰ &quot;ਲੋੜੀਂਦਾ&quot; ਵਜੋਂ ਮਜਬੂਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਇਹ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਜ਼ਰੂਰੀ ਹੈ ਕਿ ਸ਼ਿਪਿੰਗ ਪਤੇ ਨੂੰ ਬਿਲਿੰਗ ਪਤੇ &#39;ਤੇ ਕਾਪੀ ਕੀਤਾ ਜਾ ਸਕੇ ਜਦੋਂ ਉਸ ਵਿਕਲਪ ਦੀ ਜਾਂਚ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਨਹੀਂ ਤਾਂ ਗਾਹਕ ਚੈੱਕਆਉਟ ਫਾਰਮ ਨੂੰ ਪੂਰਾ ਕਰਨ ਦੇ ਯੋਗ ਨਹੀਂ ਹੋ ਸਕਦਾ।','Settings profiles' => 'ਸੈਟਿੰਗਾਂ ਪ੍ਰੋਫਾਈਲਾਂ','Settings profile' => 'ਸੈਟਿੰਗਾਂ ਪ੍ਰੋਫਾਈਲ','You do not have permission to perform this action.' => 'ਤੁਹਾਨੂੰ ਇਹ ਕਾਰਵਾਈ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।','You do not have permission to activate plugins.' => 'ਤੁਹਾਡੇ ਕੋਲ ਪਲੱਗਇਨਾਂ ਨੂੰ ਕਿਰਿਆਸ਼ੀਲ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।','Missing plugin.' => 'ਪਲੱਗਇਨ ਗੁੰਮ ਹੈ।','Plugin activated.' => 'ਪਲੱਗਇਨ ਕਿਰਿਆਸ਼ੀਲ ਹੈ।','The following changes will be applied:' => 'ਹੇਠ ਲਿਖੀਆਂ ਤਬਦੀਲੀਆਂ ਲਾਗੂ ਕੀਤੀਆਂ ਜਾਣਗੀਆਂ:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ 5.0 ਤੋਂ, ਸੈਟਿੰਗਾਂ ਨੂੰ ਵੱਖਰੇ ਢੰਗ ਨਾਲ ਸੁਰੱਖਿਅਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਪੁਰਾਣੇ ਵਿਕਲਪ ਅਜੇ ਵੀ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਟੋਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਤਾਂ ਜੋ ਲੋੜ ਪੈਣ &#39;ਤੇ ਪਿਛਲੇ ਸੰਸਕਰਣਾਂ ਵਿੱਚ ਡਾਊਨਗ੍ਰੇਡ ਕੀਤੇ ਜਾ ਸਕਣ।','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'ਤੁਹਾਡਾ ਸਟੋਰ ਨਵੀਆਂ ਸੈਟਿੰਗਾਂ &#39;ਤੇ ਲਗਭਗ 2 ਹਫ਼ਤਿਆਂ ਤੋਂ ਚੱਲ ਰਿਹਾ ਹੈ ਤਾਂ ਜੋ ਤੁਸੀਂ ਡੇਟਾਬੇਸ ਵਿੱਚ ਸਟੋਰ ਕੀਤੇ ਪੁਰਾਣੇ ਵਿਕਲਪਾਂ ਨੂੰ ਸਾਫ਼ ਕਰ ਸਕੋ। ਕਿਰਪਾ ਕਰਕੇ ਧਿਆਨ ਦਿਓ ਕਿ ਸਫਾਈ ਤੋਂ ਬਾਅਦ, ਜੇਕਰ ਤੁਹਾਨੂੰ ਪਲੱਗਇਨ ਦੇ ਪਿਛਲੇ ਸੰਸਕਰਣਾਂ &#39;ਤੇ ਡਾਊਨਗ੍ਰੇਡ ਕਰਨ ਦੀ ਲੋੜ ਹੈ ਤਾਂ ਇਹ ਸਾਰੀਆਂ ਸੈਟਿੰਗਾਂ ਲਈ ਡਿਫੌਲਟ ਮੁੱਲਾਂ ਦੀ ਵਰਤੋਂ ਕਰੇਗਾ।','Fluid Checkout settings cleanup' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਸੈਟਿੰਗਾਂ ਦੀ ਸਫ਼ਾਈ','Delete leftover options' => 'ਬਚੇ ਹੋਏ ਵਿਕਲਪਾਂ ਨੂੰ ਮਿਟਾਓ','Help us improve Fluid Checkout' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰੋ','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ਤੇਜ਼ ਸਹਾਇਤਾ ਪ੍ਰਾਪਤ ਕਰਨ ਅਤੇ ਅਨੁਕੂਲਤਾ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਅਤੇ ਪ੍ਰਭਾਵ ਨੂੰ ਮਾਪਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰਨ ਲਈ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨਾਲ ਅਗਿਆਤ ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਾਂ ਸਾਂਝੀਆਂ ਕਰੋ। ਕੋਈ ਗਾਹਕ, ਉਪਭੋਗਤਾ, ਜਾਂ ਸੰਵੇਦਨਸ਼ੀਲ ਡੇਟਾ ਸ਼ਾਮਲ ਨਹੀਂ ਹੈ। ਤੁਸੀਂ ਟੂਲ ਸੈਟਿੰਗਾਂ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਕੀ ਸਾਂਝਾ ਕਰਨਾ ਹੈ ਇਹ ਚੁਣ ਸਕਦੇ ਹੋ।','Enable site environment reports' => 'ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਾਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Review settings' => 'ਸੈਟਿੰਗਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ','This preview has expired. Reload the admin page to start a new preview.' => 'ਇਸ ਝਲਕ ਦੀ ਮਿਆਦ ਪੁੱਗ ਗਈ ਹੈ। ਇੱਕ ਨਵਾਂ ਝਲਕ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਐਡਮਿਨ ਪੰਨੇ ਨੂੰ ਰੀਲੋਡ ਕਰੋ।','Preview expired' => 'ਪੂਰਵ-ਝਲਕ ਦੀ ਮਿਆਦ ਸਮਾਪਤ ਹੋ ਗਈ','Orders cannot be placed in the preview.' => 'ਪੂਰਵਦਰਸ਼ਨ ਵਿੱਚ ਆਰਡਰ ਨਹੀਂ ਦਿੱਤੇ ਜਾ ਸਕਦੇ।','Logging in is not available in the preview.' => 'ਪੂਰਵਦਰਸ਼ਨ ਵਿੱਚ ਲੌਗਇਨ ਕਰਨਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।','Accounts cannot be created in the preview.' => 'ਪੂਰਵਦਰਸ਼ਨ ਵਿੱਚ ਖਾਤੇ ਨਹੀਂ ਬਣਾਏ ਜਾ ਸਕਦੇ।','Requests to other sites are blocked in the preview.' => 'ਦੂਜੀਆਂ ਸਾਈਟਾਂ ਲਈ ਬੇਨਤੀਆਂ ਨੂੰ ਪੂਰਵਦਰਸ਼ਨ ਵਿੱਚ ਬਲੌਕ ਕੀਤਾ ਗਿਆ ਹੈ।','Processing…' => 'ਪ੍ਰਕਿਰਿਆ ਕੀਤੀ ਜਾ ਰਹੀ ਹੈ...','Something went wrong. Please try again.' => 'ਕੁਝ ਗਲਤ ਹੋ ਗਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Activate plugin' => 'ਪਲੱਗਇਨ ਸਰਗਰਮ ਕਰੋ','Fluid Checkout PRO - The complete checkout package' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਪ੍ਰੋ - ਪੂਰਾ ਚੈੱਕਆਉਟ ਪੈਕੇਜ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'ਸਾਰੀਆਂ PRO ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ + ਸਾਰੇ ਐਡ-ਆਨ, ਇੱਕ ਕੀਮਤ। ਡਿਜ਼ਾਈਨ ਟੈਂਪਲੇਟ, ਅਨੁਕੂਲਿਤ ਕਾਰਟ ਅਤੇ ਆਰਡਰ ਪ੍ਰਾਪਤ ਪੰਨੇ, ਖਾਤਾ ਮੇਲ, ਅਤੇ ਹੋਰ ਬਹੁਤ ਕੁਝ।','Optimized order pay page' => 'ਅਨੁਕੂਲਿਤ ਆਰਡਰ ਭੁਗਤਾਨ ਪੰਨਾ','Express checkout buttons from supported payment methods' => 'ਸਮਰਥਿਤ ਭੁਗਤਾਨ ਵਿਧੀਆਂ ਤੋਂ ਐਕਸਪ੍ਰੈਸ ਚੈੱਕਆਉਟ ਬਟਨ','Delayed account creation' => 'ਦੇਰੀ ਨਾਲ ਖਾਤਾ ਬਣਾਇਆ ਗਿਆ','Address autocomplete with Google Maps APIs' => 'Google Maps API ਦੇ ਨਾਲ ਪਤਾ ਆਟੋਕੰਪਲੀਟ','Multiple saved addresses with the address book' => 'ਐਡਰੈੱਸ ਬੁੱਕ ਦੇ ਨਾਲ ਕਈ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਪਤੇ','EU-VAT assistant' => 'EU-VAT ਸਹਾਇਕ','Hide this section' => 'ਇਸ ਭਾਗ ਨੂੰ ਲੁਕਾਓ','Learn more' => 'ਜਿਆਦਾ ਜਾਣੋ','Get early access' => 'ਜਲਦੀ ਪਹੁੰਚ ਪ੍ਰਾਪਤ ਕਰੋ','Activate add-on' => 'ਐਡ-ਆਨ ਨੂੰ ਕਿਰਿਆਸ਼ੀਲ ਕਰੋ','Get more out of your checkout journey' => 'ਆਪਣੀ ਚੈੱਕਆਉਟ ਯਾਤਰਾ ਦਾ ਵੱਧ ਤੋਂ ਵੱਧ ਲਾਭ ਉਠਾਓ','Test API key' => 'API ਕੁੰਜੀ ਦੀ ਜਾਂਚ ਕਰੋ','Guided setup' => 'ਗਾਈਡਡ ਸੈੱਟਅੱਪ','Options' => 'ਵਿਕਲਪ','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">ਚੈੱਕਆਉਟ ਵਿਕਲਪਾਂ</a> &#39;ਤੇ ਲੇਆਉਟ ਅਤੇ ਡਿਜ਼ਾਈਨ ਸੈੱਟ ਕਰੋ।','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'ਮਹਿਮਾਨ ਚੈੱਕਆਉਟ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ ਅਤੇ/ਜਾਂ <a href="%s">ਗਾਹਕ ਖਾਤੇ ਸੈਟਿੰਗਾਂ ਦੀ</a> ਸਮੀਖਿਆ ਕਰੋ।','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ਅਨੁਕੂਲਿਤ <a href="%1$s">ਕਾਰਟ</a> ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ, <a href="%2$s">ਧੰਨਵਾਦ ਕਰੋ</a> ਅਤੇ <a href="%3$s">ਭੁਗਤਾਨ ਪੰਨਿਆਂ ਦਾ ਆਰਡਰ ਕਰੋ</a> ।','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google ਨਕਸ਼ੇ ਤੋਂ <a href="%s">ਪਤਾ ਆਟੋਕੰਪਲੀਟ ਨੂੰ</a> ਸਮਰੱਥ ਬਣਾਓ।','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">ਐਡਰੈੱਸ ਬੁੱਕ</a> ਨਾਲ ਕਈ ਸੇਵ ਕੀਤੇ ਪਤਿਆਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ।','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'ਜਾਂਚ ਕਰੋ ਕਿ ਕੀ ਥੀਮ ਜਾਂ ਤੁਹਾਡੇ ਦੁਆਰਾ ਸਥਾਪਿਤ ਕੀਤੇ ਗਏ ਹੋਰ ਪਲੱਗਇਨਾਂ ਲਈ ਕੋਈ <a href="%s">ਏਕੀਕਰਨ ਵਿਕਲਪ</a> ਉਪਲਬਧ ਹਨ।','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ਤੇਜ਼ ਸਹਾਇਤਾ ਪ੍ਰਾਪਤ ਕਰੋ ਅਤੇ ਅਨੁਕੂਲਤਾ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਅਤੇ ਪ੍ਰਭਾਵ ਨੂੰ ਮਾਪਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰੋ। ਟੂਲ ਸੈਟਿੰਗਾਂ ਤੋਂ <a href="%s">ਵਰਤੋਂ ਟਰੈਕਿੰਗ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ</a> ।','Missing settings tab.' => 'ਸੈਟਿੰਗਜ਼ ਟੈਬ ਗੁੰਮ ਹੈ।','Getting started' => 'ਸ਼ੁਰੂ ਕਰਨਾ','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>ਬਹੁਤ ਵਧੀਆ! ਤੁਹਾਡਾ ਚੈੱਕਆਉਟ ਪੰਨਾ ਹੁਣ ਫਲੂਇਡ ਚੈੱਕਆਉਟ &#39;ਤੇ ਚੱਲ ਰਿਹਾ ਹੈ।</strong> ਸ਼ੁਰੂਆਤ ਕਰਨ ਲਈ ਇੱਥੇ ਕੁਝ ਕਦਮ ਹਨ:','Completed' => 'ਪੂਰਾ ਹੋਇਆ','Preview report data' => 'ਰਿਪੋਰਟ ਡੇਟਾ ਦਾ ਪੂਰਵਦਰਸ਼ਨ ਕਰੋ','Send now' => 'ਹੁਣੇ ਭੇਜੋ','Auto-detect' => 'ਸਵੈ-ਖੋਜ','Afrikaans' => 'ਅਫ਼ਰੀਕੀ','Albanian' => 'ਅਲਬਾਨੀਅਨ','Amharic' => 'ਅਮਹਾਰਿਕ','Arabic' => 'ਅਰਬੀ','Armenian' => 'ਅਰਮੀਨੀਆਈ','Azerbaijani' => 'ਅਜ਼ਰਬਾਈਜਾਨੀ','Basque' => 'ਬਾਸਕ','Belarusian' => 'ਬੇਲਾਰੂਸੀ','Bengali' => 'ਬੰਗਾਲੀ','Bosnian' => 'ਬੋਸਨੀਆਈ','Bulgarian' => 'ਬੁਲਗਾਰੀਅਨ','Burmese' => 'ਬਰਮੀ','Catalan' => 'ਕੈਟਲਨ','Chinese' => 'ਚੀਨੀ','Chinese (Simplified)' => 'ਚੀਨੀ (ਸਰਲੀਕ੍ਰਿਤ)','Chinese (Hong Kong)' => 'ਚੀਨੀ (ਹਾਂਗ ਕਾਂਗ)','Chinese (Traditional)' => 'ਚੀਨੀ (ਰਵਾਇਤੀ)','Croatian' => 'ਕ੍ਰੋਏਸ਼ੀਆਈ','Czech' => 'ਚੈੱਕ','Danish' => 'ਡੈਨਿਸ਼','Dutch' => 'ਡੱਚ','English' => 'ਅੰਗਰੇਜ਼ੀ','English (Australian)' => 'ਅੰਗਰੇਜ਼ੀ (ਆਸਟ੍ਰੇਲੀਅਨ)','English (Great Britain)' => 'ਅੰਗਰੇਜ਼ੀ (ਗ੍ਰੇਟ ਬ੍ਰਿਟੇਨ)','Estonian' => 'ਇਸਤੋਨੀਅਨ','Farsi' => 'ਫਾਰਸੀ','Finnish' => 'ਫਿਨਿਸ਼','Filipino' => 'ਫਿਲੀਪੀਨੋ','French' => 'ਫ੍ਰੈਂਚ','French (Canadian)' => 'ਫ੍ਰੈਂਚ (ਕੈਨੇਡੀਅਨ)','Galician' => 'ਗੈਲੀਸ਼ਿਅਨ','Georgian' => 'ਜਾਰਜੀਆਈ','German' => 'ਜਰਮਨ','Greek' => 'ਯੂਨਾਨੀ','Gujarati' => 'ਗੁਜਰਾਤੀ','Hebrew' => 'ਇਬਰਾਨੀ','Hindi' => 'ਹਿੰਦੀ','Hungarian' => 'ਹੰਗਰੀਆਈ','Icelandic' => 'ਆਈਸਲੈਂਡਿਕ','Indonesian' => 'ਇੰਡੋਨੇਸ਼ੀਆਈ','Italian' => 'ਇਤਾਲਵੀ','Japanese' => 'ਜਪਾਨੀ','Kannada' => 'ਕੰਨੜ','Kazakh' => 'ਕਜ਼ਾਖ','Khmer' => 'ਖਮੇਰ','Korean' => 'ਕੋਰੀਆਈ','Kyrgyz' => 'ਕਿਰਗਿਜ਼','Lao' => 'ਲਾਓ','Latvian' => 'ਲਾਤਵੀਅਨ','Lithuanian' => 'ਲਿਥੁਆਨੀਅਨ','Macedonian' => 'ਮੈਸੇਡੋਨੀਅਨ','Malay' => 'ਮਾਲੇਈ','Malayalam' => 'ਮਲਿਆਲਮ','Marathi' => 'ਮਰਾਠੀ','Mongolian' => 'ਮੰਗੋਲੀਆਈ','Nepali' => 'ਨੇਪਾਲੀ','Norwegian' => 'ਨਾਰਵੇਜੀਅਨ','Polish' => 'ਪੋਲਿਸ਼','Portuguese' => 'ਪੁਰਤਗਾਲੀ','Portuguese (Brazil)' => 'ਪੁਰਤਗਾਲੀ (ਬ੍ਰਾਜ਼ੀਲ)','Portuguese (Portugal)' => 'ਪੁਰਤਗਾਲੀ (ਪੁਰਤਗਾਲ)','Punjabi' => 'ਪੰਜਾਬੀ','Romanian' => 'ਰੋਮਾਨੀਆਈ','Russian' => 'ਰੂਸੀ','Serbian' => 'ਸਰਬੀਆਈ','Sinhalese' => 'ਸਿੰਹਾਲੀ','Slovak' => 'ਸਲੋਵਾਕ','Slovenian' => 'ਸਲੋਵੇਨੀਅਨ','Spanish' => 'ਸਪੈਨਿਸ਼','Spanish (Latin America)' => 'ਸਪੈਨਿਸ਼ (ਲਾਤੀਨੀ ਅਮਰੀਕਾ)','Swahili' => 'ਸਵਾਹਿਲੀ','Swedish' => 'ਸਵੀਡਿਸ਼','Tamil' => 'ਤਾਮਿਲ','Telugu' => 'ਤੇਲਗੂ','Thai' => 'ਥਾਈ','Turkish' => 'ਤੁਰਕੀ','Ukrainian' => 'ਯੂਕਰੇਨੀ','Urdu' => 'ਉਰਦੂ','Vietnamese' => 'ਵੀਅਤਨਾਮੀ','Zulu' => 'ਜ਼ੁਲੂ','Google address autocomplete' => 'ਗੂਗਲ ਐਡਰੈੱਸ ਆਟੋਕੰਪਲੀਟ','Google Places API version' => 'ਗੂਗਲ ਪਲੇਸ ਏਪੀਆਈ ਵਰਜਨ','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'ਚੁਣੋ ਕਿ Google Places API ਦਾ ਕਿਹੜਾ ਵਰਜਨ ਵਰਤਣਾ ਹੈ। ਅਸੀਂ ਜਿੰਨੀ ਜਲਦੀ ਹੋ ਸਕੇ ਨਵੇਂ Places API &#39;ਤੇ ਜਾਣ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਕਰਦੇ ਹਾਂ।','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'ਅਸੀਂ &quot;Places API (ਨਵਾਂ)&quot; ਦੀ ਵਰਤੋਂ ਕਰਨ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਕਰਦੇ ਹਾਂ ਕਿਉਂਕਿ 1 ਮਾਰਚ, 2025 ਤੋਂ ਪ੍ਰਭਾਵੀ ਹੈ, Google &quot;Places API (Legacy)&quot; ਸੰਸਕਰਣ ਨੂੰ Legacy ਸਥਿਤੀ ਵਿੱਚ ਤਬਦੀਲ ਕਰ ਦੇਵੇਗਾ, ਮਤਲਬ ਕਿ ਤੁਸੀਂ ਹੁਣ ਇਸ ਸੇਵਾ ਨੂੰ ਨਵੀਆਂ API ਕੁੰਜੀਆਂ ਲਈ ਸਮਰੱਥ ਨਹੀਂ ਕਰ ਸਕੋਗੇ ਅਤੇ API ਦਾ ਉਹ ਸੰਸਕਰਣ ਅੰਤ ਵਿੱਚ ਹੁਣ ਉਪਲਬਧ ਨਹੀਂ ਹੋਵੇਗਾ। Legacy API ਦੀ ਵਰਤੋਂ ਕਰ ਰਹੇ ਮੌਜੂਦਾ ਖਾਤੇ ਬਿਨਾਂ ਕਿਸੇ ਰੁਕਾਵਟ ਦੇ ਕੰਮ ਕਰਨਾ ਜਾਰੀ ਰੱਖ ਸਕਦੇ ਹਨ।','(Recommended)' => '(ਸਿਫ਼ਾਰਸ਼ੀ)','Google API key' => 'ਗੂਗਲ ਏਪੀਆਈ ਕੁੰਜੀ','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'ਆਪਣੀ Google API ਕੁੰਜੀ ਪੇਸਟ ਕਰੋ ਅਤੇ ਇਸ ਵੈੱਬਸਾਈਟ ਲਈ ਕੰਮ ਕਰਨ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਟੈਸਟ ਬਟਨ ਦੀ ਵਰਤੋਂ ਕਰੋ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਕੁੰਜੀ ਵੈਧ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਡੋਮੇਨ ਲਈ ਆਗਿਆ ਹੈ, ਨਹੀਂ ਤਾਂ ਪਤਾ ਖੇਤਰ ਬਲੌਕ ਹੋ ਸਕਦਾ ਹੈ ਜਿਸ ਨਾਲ ਗਾਹਕ ਆਪਣੇ ਆਰਡਰ ਪੂਰੇ ਨਹੀਂ ਕਰ ਸਕਦੇ।','Enable Google address autocomplete' => 'ਗੂਗਲ ਐਡਰੈੱਸ ਆਟੋਕੰਪਲੀਟ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Enable address autocompletion using the Google Maps APIs.' => 'Google ਨਕਸ਼ੇ API ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਪਤਾ ਆਟੋਕੰਪਲੀਸ਼ਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ।','Google API language' => 'ਗੂਗਲ ਏਪੀਆਈ ਭਾਸ਼ਾ','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ਇਸ ਭਾਸ਼ਾ ਦੀ ਵਰਤੋਂ Google Places API ਪਤਾ ਸੁਝਾਵਾਂ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਲਈ ਕੀਤੀ ਜਾਵੇਗੀ ਅਤੇ ਪਤੇ ਵੀ ਇਸ ਭਾਸ਼ਾ ਵਿੱਚ ਸਵੈ-ਮੁਕੰਮਲ ਹੋਣਗੇ।','Result types' => 'ਨਤੀਜੇ ਦੀਆਂ ਕਿਸਮਾਂ','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ਕਿਸੇ ਵੀ ਕਿਸਮ ਦੇ ਨਤੀਜੇ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ, ਜੋ ਆਮ ਤੌਰ &#39;ਤੇ ਬਿਹਤਰ ਮੇਲ ਖਾਂਦੇ ਨਤੀਜੇ ਦਿੰਦੇ ਹਨ। <a href="%s" target="_blank">ਹੋਰ ਵੇਰਵਿਆਂ ਲਈ ਦਸਤਾਵੇਜ਼ ਵੇਖੋ</a> ।<br> ਪਤਾ ਆਟੋਕੰਪਲੀਟ ਖੇਤਰਾਂ &#39;ਤੇ ਵਾਪਸ ਜਾਣ ਲਈ 5 ਕਿਸਮਾਂ ਦੇ ਪਤਾ ਖੋਜ ਨਤੀਜੇ ਚੁਣੋ।<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ਸਮਰਥਿਤ ਕਿਸਮਾਂ</a> ਬਾਰੇ ਹੋਰ ਜਾਣਨ ਲਈ Google ਨਕਸ਼ੇ ਦਸਤਾਵੇਜ਼ &#39;ਤੇ ਜਾਓ।','Result types (Legacy API)' => 'ਨਤੀਜੇ ਦੀਆਂ ਕਿਸਮਾਂ (ਪੁਰਾਤਨ API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਕਿਸ ਕਿਸਮ ਦੇ ਪਤਾ ਖੋਜ ਨਤੀਜੇ ਵਾਪਸ ਕਰਨੇ ਹਨ।<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ਸਮਰਥਿਤ ਕਿਸਮਾਂ</a> ਬਾਰੇ ਹੋਰ ਜਾਣਨ ਲਈ Legacy Google Places API ਦੇ ਦਸਤਾਵੇਜ਼ ਵੇਖੋ।','Company fields' => 'ਕੰਪਨੀ ਦੇ ਖੇਤਰ','Enable autocomplete for the company name if available' => 'ਜੇਕਰ ਉਪਲਬਧ ਹੋਵੇ ਤਾਂ ਕੰਪਨੀ ਦੇ ਨਾਮ ਲਈ ਸਵੈ-ਮੁਕੰਮਲ ਨੂੰ ਚਾਲੂ ਕਰੋ','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'ਗੂਗਲ ਮੈਪਸ ਏਪੀਆਈ ਤੋਂ ਵਾਪਸ ਆਉਣ &#39;ਤੇ ਕੰਪਨੀ ਦੇ ਨਾਮ ਦੀ ਜਾਣਕਾਰੀ ਦੇ ਨਾਲ ਕੰਪਨੀ ਖੇਤਰ ਦੀ ਆਟੋਕੰਪਲੀਸ਼ਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ।','Business search' => 'ਕਾਰੋਬਾਰੀ ਖੋਜ','Enable search for businesses in the company field' => 'ਕੰਪਨੀ ਖੇਤਰ ਵਿੱਚ ਕਾਰੋਬਾਰਾਂ ਦੀ ਖੋਜ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'ਕੰਪਨੀ ਖੇਤਰ ਵਿੱਚ ਟਾਈਪ ਕਰਦੇ ਸਮੇਂ ਕਾਰੋਬਾਰ ਨਾਲ ਜੁੜੇ ਪਤਿਆਂ ਦੇ ਸੁਝਾਅ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ, ਫਿਰ ਸੁਝਾਵਾਂ ਵਿੱਚੋਂ ਕਾਰੋਬਾਰ ਦੀ ਚੋਣ ਕਰਨ &#39;ਤੇ ਸਾਰੇ ਪਤੇ ਖੇਤਰਾਂ ਨੂੰ ਆਟੋਕੰਪਲੀਟ ਕਰੋ।','Company result types' => 'ਕੰਪਨੀ ਦੇ ਨਤੀਜਿਆਂ ਦੀਆਂ ਕਿਸਮਾਂ','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ਆਟੋਕੰਪਲੀਟ ਕੰਪਨੀ ਖੇਤਰਾਂ &#39;ਤੇ ਵਾਪਸ ਜਾਣ ਲਈ 5 ਕਿਸਮਾਂ ਦੇ ਪਤਾ ਖੋਜ ਨਤੀਜੇ ਚੁਣੋ।<br> ਸਿਫ਼ਾਰਸ਼ੀ ਮੁੱਲ <code>establishment</code> ਹੈ, ਜਿਸ ਵਿੱਚ ਜ਼ਿਆਦਾਤਰ ਕਿਸਮਾਂ ਦੇ ਕਾਰੋਬਾਰ ਸ਼ਾਮਲ ਹੁੰਦੇ ਹਨ।<br> ਕਿਸੇ ਵੀ ਕਿਸਮ ਦੇ ਨਤੀਜੇ ਸਵੀਕਾਰ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ, ਜਿਸ ਵਿੱਚ ਉਹ ਨਤੀਜੇ ਵੀ ਸ਼ਾਮਲ ਹਨ ਜੋ ਕਾਰੋਬਾਰਾਂ ਨਾਲ ਸਬੰਧਤ ਨਹੀਂ ਹਨ।<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ਸਮਰਥਿਤ ਕਿਸਮਾਂ</a> ਬਾਰੇ ਹੋਰ ਜਾਣਨ ਲਈ Google ਨਕਸ਼ੇ ਦਸਤਾਵੇਜ਼ &#39;ਤੇ ਜਾਓ।','Google logo' => 'ਗੂਗਲ ਲੋਗੋ','Show text and logo "Powered by Google"' => '&quot;Google ਦੁਆਰਾ ਸੰਚਾਲਿਤ&quot; ਟੈਕਸਟ ਅਤੇ ਲੋਗੋ ਦਿਖਾਓ','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ਜਦੋਂ ਚੈੱਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਤਾਂ &quot;Powered by Google&quot; ਟੈਕਸਟ ਅਤੇ ਲੋਗੋ ਐਡਰੈੱਸ ਆਟੋਕੰਪਲੀਟ ਸੁਝਾਅ ਬਾਕਸ ਦੇ ਹੇਠਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਹੋਣਗੇ।','Brasil API address autocomplete' => 'ਬ੍ਰਾਜ਼ੀਲ API ਪਤਾ ਆਟੋਕੰਪਲੀਟ','Brasil API' => 'ਬ੍ਰਾਜ਼ੀਲ API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ਖੇਤਰਾਂ ਲਈ ਬ੍ਰਾਜ਼ੀਲ API ਐਡਰੈੱਸ ਆਟੋਕੰਪਲੀਟ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/ਪੋਸਟਕੋਡ ਖੇਤਰ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਪਤਿਆਂ ਨੂੰ ਪ੍ਰਾਪਤ ਕਰਨ ਅਤੇ ਆਟੋਫਿਲ ਕਰਨ ਲਈ ਬ੍ਰਾਜ਼ੀਲ API ਦੀ ਵਰਤੋਂ ਕਰੋ। ਸਿਰਫ਼ ਬ੍ਰਾਜ਼ੀਲੀਅਨ ਪਤਿਆਂ ਲਈ ਢੁਕਵਾਂ।','API version' => 'API ਵਰਜਨ','Choose which version of the Brasil API CEP method to use.' => 'ਬ੍ਰਾਜ਼ੀਲ API CEP ਵਿਧੀ ਦਾ ਕਿਹੜਾ ਸੰਸਕਰਣ ਵਰਤਣਾ ਹੈ, ਚੁਣੋ।','Address book migration' => 'ਐਡਰੈੱਸ ਬੁੱਕ ਮਾਈਗ੍ਰੇਸ਼ਨ','WooCommerce addresses' => 'WooCommerce ਪਤੇ','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce ਤੋਂ ਮੌਜੂਦਾ ਸ਼ਿਪਿੰਗ ਅਤੇ ਬਿਲਿੰਗ ਪਤਿਆਂ ਨੂੰ ਗਾਹਕਾਂ ਦੀ ਐਡਰੈੱਸ ਬੁੱਕ ਵਿੱਚ ਕਾਪੀ ਕਰੋ।','Enable the address book feature' => 'ਐਡਰੈੱਸ ਬੁੱਕ ਵਿਸ਼ੇਸ਼ਤਾ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ਗਾਹਕਾਂ ਨੂੰ ਕਈ ਪਤੇ ਸੁਰੱਖਿਅਤ ਕਰਨ ਅਤੇ ਸ਼ਿਪਿੰਗ ਅਤੇ ਬਿਲਿੰਗ ਲਈ ਵਰਤੇ ਜਾਣ ਵਾਲੇ ਡਿਫੌਲਟ ਪਤੇ ਨੂੰ ਪਰਿਭਾਸ਼ਿਤ ਕਰਨ ਦੀ ਆਗਿਆ ਦਿਓ।','Address labels' => 'ਪਤਾ ਲੇਬਲ','Allow customers to add a custom label for each address' => 'ਗਾਹਕਾਂ ਨੂੰ ਹਰੇਕ ਪਤੇ ਲਈ ਇੱਕ ਕਸਟਮ ਲੇਬਲ ਜੋੜਨ ਦੀ ਆਗਿਆ ਦਿਓ','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'ਪਤੇ ਦੇ ਲੇਬਲ ਗਾਹਕਾਂ ਲਈ ਆਪਣੇ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਪਤਿਆਂ (ਜਿਵੇਂ ਕਿ: &quot;ਮਾਂ ਦਾ ਘਰ&quot;) ਵਿੱਚ ਫਰਕ ਕਰਨਾ ਆਸਾਨ ਬਣਾਉਂਦੇ ਹਨ। ਪਤੇ ਦੇ ਲੇਬਲ ਗਾਹਕਾਂ ਲਈ ਨਿੱਜੀ ਹਨ, ਅਤੇ ਆਰਡਰ ਵੇਰਵੇ ਪੰਨੇ ਜਾਂ ਇਨਵੌਇਸਾਂ &#39;ਤੇ ਪ੍ਰਦਰਸ਼ਿਤ ਜਾਂ ਪ੍ਰਿੰਟ ਨਹੀਂ ਕੀਤੇ ਜਾਣਗੇ।','Display layout' => 'ਡਿਸਪਲੇ ਲੇਆਉਟ','Choose how saved addresses are displayed at checkout and on the cart.' => 'ਚੁਣੋ ਕਿ ਚੈੱਕਆਉਟ ਵੇਲੇ ਅਤੇ ਕਾਰਟ &#39;ਤੇ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਪਤੇ ਕਿਵੇਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕੀਤੇ ਜਾਣ।','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ਚੈੱਕਆਉਟ ਅਤੇ ਕਾਰਟ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਖਾਤਾ ਪੰਨੇ &#39;ਤੇ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਪਤੇ ਹਮੇਸ਼ਾ ਕਾਰਡ ਲੇਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ।','Address cards' => 'ਪਤਾ ਕਾਰਡ','Address list' => 'ਪਤਾ ਸੂਚੀ','Dropdown field' => 'ਡ੍ਰੌਪਡਾਉਨ ਖੇਤਰ','Address search' => 'ਪਤਾ ਖੋਜ','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ਜਦੋਂ ਗਾਹਕ ਕੋਲ ਘੱਟੋ-ਘੱਟ ਇੰਨੀ ਗਿਣਤੀ ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਪਤੇ ਉਪਲਬਧ ਹੋਣ ਤਾਂ ਫਰੰਟਐਂਡ &#39;ਤੇ ਪਤਾ ਖੋਜ ਫਿਲਟਰ ਦਿਖਾਓ।','Not used when display layout is set to dropdown field.' => 'ਜਦੋਂ ਡਿਸਪਲੇ ਲੇਆਉਟ ਡ੍ਰੌਪਡਾਉਨ ਖੇਤਰ ਤੇ ਸੈੱਟ ਹੁੰਦਾ ਹੈ ਤਾਂ ਇਸਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ।','Addresses' => 'ਪਤੇ','Enable cart page optimizations to see more options' => 'ਹੋਰ ਵਿਕਲਪ ਦੇਖਣ ਲਈ ਕਾਰਟ ਪੇਜ ਅਨੁਕੂਲਤਾ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Sticky order summary' => 'ਸਟਿੱਕੀ ਆਰਡਰ ਸਾਰਾਂਸ਼','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ਕਾਰਟ ਪੰਨੇ &#39;ਤੇ ਕੂਪਨ ਕੋਡ ਸੈਕਸ਼ਨ ਨੂੰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਵਾਲੀ ਸਥਿਤੀ ਚੁਣੋ। ਸਿਰਫ਼ ਉਦੋਂ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ AJAX ਕਾਰਟ ਸਮਰੱਥ ਹੋਵੇ, ਅਤੇ ਜੇਕਰ WooCommerce ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਕੂਪਨ ਕੋਡਾਂ ਦੀ ਵਰਤੋਂ ਸਮਰੱਥ ਹੋਵੇ।','Layout of cross-sell' => 'ਕਰਾਸ-ਸੇਲ ਦਾ ਖਾਕਾ','Cross-sells displayed' => 'ਕਰਾਸ-ਸੇਲ ਪ੍ਰਦਰਸ਼ਿਤ','Items' => 'ਆਈਟਮਾਂ','Cart page optimization' => 'ਕਾਰਟ ਪੰਨਾ ਸੁਯੋਗਕਰਨ','Give your cart the same clear, conversion-focused layout as your checkout.' => 'ਆਪਣੀ ਕਾਰਟ ਨੂੰ ਆਪਣੇ ਚੈੱਕਆਉਟ ਵਾਂਗ ਹੀ ਸਪਸ਼ਟ, ਪਰਿਵਰਤਨ-ਕੇਂਦ੍ਰਿਤ ਲੇਆਉਟ ਦਿਓ।','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ਇਕਸਾਰ ਖਰੀਦ ਯਾਤਰਾ ਲਈ ਕਾਰਟ ਲੇਆਉਟ ਨੂੰ ਚੈੱਕਆਉਟ ਪੰਨੇ ਨਾਲ ਮਿਲਾਓ।','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'ਕਾਰਟ ਨੂੰ ਹਮੇਸ਼ਾ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਅੱਪਡੇਟ ਰੱਖੋ, ਮਾਤਰਾ ਬਦਲਣ &#39;ਤੇ ਪੂਰਾ ਪੰਨਾ ਰੀਲੋਡ ਨਹੀਂ ਹੁੰਦਾ।','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ਕੂਪਨ ਕੋਡ, ਸ਼ਿਪਿੰਗ, ਅਤੇ ਕਰਾਸ-ਸੇਲ ਬਿਲਕੁਲ ਉੱਥੇ ਰੱਖੋ ਜਿੱਥੇ ਉਹ ਸਭ ਤੋਂ ਵਧੀਆ ਰੂਪਾਂਤਰਿਤ ਹੁੰਦੇ ਹਨ।','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'ਸਕ੍ਰੌਲ ਕਰਦੇ ਸਮੇਂ ਆਰਡਰ ਸੰਖੇਪ ਨੂੰ ਦ੍ਰਿਸ਼ਮਾਨ ਰੱਖੋ, ਅਤੇ ਜਿੱਥੇ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਭਰੋਸਾ ਦੇਣ ਦੀ ਲੋੜ ਹੋਵੇ, ਉੱਥੇ ਵਿਸ਼ਵਾਸ ਚਿੰਨ੍ਹ ਸ਼ਾਮਲ ਕਰੋ।','Columns' => 'ਕਾਲਮ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'ਚੈੱਕਆਉਟ ਕਦਮਾਂ, ਆਰਡਰ ਸੰਖੇਪ ਅਤੇ ਹੋਰ ਭਾਗਾਂ ਲਈ ਆਮ ਸ਼ੈਲੀਆਂ। ਹੋਰ ਚੈੱਕਆਉਟ, ਕਾਰਟ, ਧੰਨਵਾਦ (ਆਰਡਰ ਪ੍ਰਾਪਤ ਹੋਇਆ), ਅਤੇ ਆਰਡਰ ਪੰਨਿਆਂ ਨੂੰ ਵੇਖਣ &#39;ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;ਸਪਲਿਟ&quot;</em> ਡਿਜ਼ਾਈਨ ਟੈਂਪਲੇਟ ਦੇ ਨਾਲ <em>&quot;1 ਕਾਲਮ&quot;</em> ਲੇਆਉਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ, ਇੱਕ ਸੱਜਾ ਕਾਲਮ ਸਿਰਫ਼ ਤਾਂ ਹੀ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ ਜੇਕਰ ਪੰਨਾ ਸਾਈਡਬਾਰ ਵਿਜੇਟ ਖੇਤਰ ਕਿਰਿਆਸ਼ੀਲ ਹੈ (ਚੈੱਕਆਉਟ ਸਾਈਡਬਾਰ, ਕਾਰਟ ਸਾਈਡਬਾਰ, ਜਾਂ ਆਰਡਰ ਪ੍ਰਾਪਤ ਸਾਈਡਬਾਰ)। ਨਹੀਂ ਤਾਂ ਪੰਨਾ ਸਪਲਿਟ ਸਟਾਈਲ ਦੇ ਨਾਲ ਇੱਕ ਸਿੰਗਲ ਕਾਲਮ ਦੇ ਰੂਪ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ।','Split column background' => 'ਕਾਲਮ ਬੈਕਗ੍ਰਾਊਂਡ ਨੂੰ ਵੰਡੋ','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ਸਪਲਿਟ ਡਿਜ਼ਾਈਨ ਸੈਕੰਡਰੀ ਕਾਲਮ ਲਈ ਇੱਕ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਚੁਣੋ। ਆਰਡਰ ਸੰਖੇਪ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ।','Page templates' => 'ਪੰਨਾ ਟੈਂਪਲੇਟ','Checkout template' => 'ਚੈੱਕਆਉਟ ਟੈਮਪਲੇਟ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ਚੈੱਕਆਉਟ &#39;ਤੇ ਘੱਟ ਭਟਕਣਾਵਾਂ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। <a href="https://baymard.com/blog/cart-abandonment" target="_blank">ਕਾਰਟ ਛੱਡਣ ਬਾਰੇ ਖੋਜ ਪੜ੍ਹੋ</a> ।','Sticky progress bar' => 'ਸਟਿੱਕੀ ਪ੍ਰਗਤੀ ਪੱਟੀ','Progress bar style' => 'ਤਰੱਕੀ ਪੱਟੀ ਸ਼ੈਲੀ','Order totals' => 'ਆਰਡਰ ਕੁੱਲ','Background color' => 'ਪਿਛੋਕੜ ਦਾ ਰੰਗ','Action link' => 'ਕਾਰਵਾਈ ਲਿੰਕ','Mobile order summary' => 'ਮੋਬਾਈਲ ਆਰਡਰ ਸਾਰਾਂਸ਼','Mobile initial state' => 'ਮੋਬਾਈਲ ਦੀ ਸ਼ੁਰੂਆਤੀ ਸਥਿਤੀ','Enable editing cart items at checkout' => 'ਚੈੱਕਆਉਟ &#39;ਤੇ ਕਾਰਟ ਆਈਟਮਾਂ ਦਾ ਸੰਪਾਦਨ ਚਾਲੂ ਕਰੋ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਸਿੱਧੇ ਉਤਪਾਦ ਦੀ ਮਾਤਰਾ ਬਦਲਣ ਜਾਂ ਚੀਜ਼ਾਂ ਨੂੰ ਹਟਾਉਣ ਦੀ ਆਗਿਆ ਦਿਓ।','Cart item errors' => 'ਕਾਰਟ ਆਈਟਮ ਸੰਬੰਧੀ ਗੜਬੜੀਆਂ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ਸਿਰਫ਼ ਉਦੋਂ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਕੂਪਨ ਕੋਡ ਚੈੱਕਆਉਟ ਜਾਂ ਕਾਰਟ ਪੰਨਿਆਂ &#39;ਤੇ ਇੱਕ ਵੱਖਰੇ ਭਾਗ ਵਜੋਂ ਪ੍ਰਦਰਸ਼ਿਤ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਜੇਕਰ ਕੂਪਨ ਕੋਡਾਂ ਦੀ ਵਰਤੋਂ WooCommerce ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਮਰੱਥ ਹੁੰਦੀ ਹੈ।','Coupon codes position' => 'ਕੂਪਨ ਕੋਡ ਸਥਿਤੀ','Apply coupon button' => 'ਕੂਪਨ ਬਟਨ ਲਾਗੂ ਕਰੋ','Select style of the "apply coupon" button.' => '&quot;ਲਾਗੂ ਕੂਪਨ&quot; ਬਟਨ ਦੀ ਸ਼ੈਲੀ ਚੁਣੋ।','Address line 2' => 'ਪਤਾ ਲਾਈਨ 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ਇਹ ਸੈਟਿੰਗ ਚੈੱਕਆਉਟ ਅਤੇ ਸਥਾਨਕ ਪਿਕਅੱਪ ਭਾਗਾਂ ਵਿਚਕਾਰ ਸਾਂਝੀ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਸਥਾਨਕ ਪਿਕਅੱਪ ਭਾਗ &#39;ਤੇ, ਇਹ ਇਹ ਵੀ ਫੈਸਲਾ ਕਰਦਾ ਹੈ ਕਿ ਸ਼ਿਪ/ਪਿਕਅੱਪ ਚੋਣਕਾਰ ਸ਼ਿਪਿੰਗ ਵਿਧੀ ਭਾਗ ਦੇ ਅੰਦਰ (ਪਤੇ ਤੋਂ ਪਹਿਲਾਂ) ਜਾਂ ਇੱਕ ਵੱਖਰੇ ਭਾਗ (ਬਾਅਦ) ਦੇ ਰੂਪ ਵਿੱਚ ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ।','Customer accounts' => 'ਗਾਹਕ ਖਾਤੇ','Guest checkout' => 'ਮਹਿਮਾਨ ਚੈੱਕਆਉਟ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce ਖਾਤਾ ਸੈਟਿੰਗਾਂ ਪੰਨੇ ਤੋਂ ਮਹਿਮਾਨ ਚੈੱਕਆਉਟ, ਲੌਗਇਨ, ਅਤੇ ਖਾਤਾ ਬਣਾਉਣ ਦੇ ਵਿਕਲਪ। ਉਹਨਾਂ ਨੂੰ ਤੁਹਾਡੀ ਸਹੂਲਤ ਲਈ ਇੱਥੇ ਪ੍ਰਬੰਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਇਸ ਲਈ ਤੁਸੀਂ ਹਰੇਕ ਸੈਟਿੰਗ ਪ੍ਰੋਫਾਈਲ ਲਈ ਵੱਖ-ਵੱਖ ਮੁੱਲਾਂ ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦੇ ਹੋ।','Allow customers to checkout without an account' => 'ਗਾਹਕਾਂ ਨੂੰ ਬਿਨਾਂ ਖਾਤੇ ਦੇ ਚੈੱਕਆਉਟ ਕਰਨ ਦੀ ਆਗਿਆ ਦਿਓ','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ਇਸ ਲਈ <strong>ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ</strong> ਤਾਂ ਜੋ ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਖਾਤਾ ਬਣਾਉਣ ਜਾਂ ਲੌਗਇਨ ਕਰਨ ਲਈ ਨਾ ਕਿਹਾ ਜਾਵੇ, ਜਿਸ ਨਾਲ ਪਰਿਵਰਤਨ ਦਰਾਂ ਘੱਟ ਸਕਦੀਆਂ ਹਨ।','When disabled, customers must log in or create an account to complete the purchase.' => 'ਜਦੋਂ ਇਹ ਬੰਦ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਗਾਹਕਾਂ ਨੂੰ ਖਰੀਦਦਾਰੀ ਪੂਰੀ ਕਰਨ ਲਈ ਲੌਗਇਨ ਕਰਨਾ ਜਾਂ ਖਾਤਾ ਬਣਾਉਣਾ ਲਾਜ਼ਮੀ ਹੁੰਦਾ ਹੈ।','Login at checkout' => 'ਚੈੱਕਆਉਟ &#39;ਤੇ ਲੌਗਇਨ ਕਰੋ','Enable log-in during checkout' => 'ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਲੌਗ-ਇਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Show a link for returning customers to log in from the checkout page.' => 'ਵਾਪਸ ਆਉਣ ਵਾਲੇ ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਪੰਨੇ ਤੋਂ ਲੌਗਇਨ ਕਰਨ ਲਈ ਇੱਕ ਲਿੰਕ ਦਿਖਾਓ।','Account creation' => 'ਖਾਤਾ ਬਣਾਉਣਾ','Allow customers to create an account during checkout' => 'ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਖਾਤਾ ਬਣਾਉਣ ਦੀ ਆਗਿਆ ਦਿਓ','Customers can create an account before placing their order.' => 'ਗਾਹਕ ਆਪਣਾ ਆਰਡਰ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਖਾਤਾ ਬਣਾ ਸਕਦੇ ਹਨ।','Allow customers to create an account from the My account page' => 'ਗਾਹਕਾਂ ਨੂੰ ਮੇਰਾ ਖਾਤਾ ਪੰਨੇ ਤੋਂ ਖਾਤਾ ਬਣਾਉਣ ਦੀ ਆਗਿਆ ਦਿਓ','Customers can register a new account from the My account page.' => 'ਗਾਹਕ ਮੇਰਾ ਖਾਤਾ ਪੰਨੇ ਤੋਂ ਇੱਕ ਨਵਾਂ ਖਾਤਾ ਰਜਿਸਟਰ ਕਰ ਸਕਦੇ ਹਨ।','Username' => 'ਯੂਜ਼ਰਨੇਮ','Generate from customer\'s name' => 'ਗਾਹਕ ਦੇ ਨਾਮ ਤੋਂ ਤਿਆਰ ਕਰੋ','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ਇਸ ਲਈ <strong>ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ</strong> ਤਾਂ ਜੋ ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਉਪਭੋਗਤਾ ਨਾਮ ਚੁਣਨ ਲਈ ਨਾ ਕਿਹਾ ਜਾਵੇ, ਜੋ ਪਰਿਵਰਤਨ ਦਰਾਂ ਨੂੰ ਘਟਾ ਸਕਦਾ ਹੈ।','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ਇੱਕ ਉਪਭੋਗਤਾ ਨਾਮ ਗਾਹਕ ਦੇ ਨਾਮ ਤੋਂ, ਜਾਂ ਜਦੋਂ ਨਾਮ ਵਰਤਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ ਤਾਂ ਈਮੇਲ ਪਤੇ ਤੋਂ ਤਿਆਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।','Password' => 'ਪਾਸਵਰਡ','Send password setup link' => 'ਪਾਸਵਰਡ ਸੈੱਟਅੱਪ ਲਿੰਕ ਭੇਜੋ','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ਇਸ ਲਈ <strong>ਸਿਫਾਰਸ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ</strong> ਤਾਂ ਜੋ ਗਾਹਕਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਪਾਸਵਰਡ ਸੈੱਟ ਕਰਨ ਲਈ ਨਾ ਕਿਹਾ ਜਾਵੇ, ਜਿਸ ਨਾਲ ਪਰਿਵਰਤਨ ਦਰਾਂ ਘੱਟ ਸਕਦੀਆਂ ਹਨ।','Customers receive an email to create their password securely.' => 'ਗਾਹਕਾਂ ਨੂੰ ਆਪਣਾ ਪਾਸਵਰਡ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਬਣਾਉਣ ਲਈ ਇੱਕ ਈਮੇਲ ਪ੍ਰਾਪਤ ਹੁੰਦੀ ਹੈ।','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'ਰਜਿਸਟਰਡ ਗਾਹਕਾਂ ਨੂੰ ਲੌਗਇਨ ਕੀਤੇ ਬਿਨਾਂ ਚੈੱਕਆਉਟ ਪੂਰਾ ਕਰਨ ਦਿਓ ਅਤੇ ਸੰਪਰਕ ਵੇਰਵੇ ਮੇਲ ਖਾਂਦੇ ਸਮੇਂ ਆਰਡਰ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਮੌਜੂਦਾ ਖਾਤੇ ਨਾਲ ਜੋੜੋ।','Existing account message' => 'ਮੌਜੂਦਾ ਖਾਤਾ ਸੁਨੇਹਾ','Let customers create an account after placing their order, from the thank you page.' => 'ਗਾਹਕਾਂ ਨੂੰ ਆਪਣਾ ਆਰਡਰ ਦੇਣ ਤੋਂ ਬਾਅਦ, ਧੰਨਵਾਦ ਪੰਨੇ ਤੋਂ ਇੱਕ ਖਾਤਾ ਬਣਾਉਣ ਦਿਓ।','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ਇਸ ਭਾਗ ਵਿੱਚ ਵਿਕਲਪ ਉਦੋਂ ਉਪਲਬਧ ਹੁੰਦੇ ਹਨ ਜਦੋਂ ਮਹਿਮਾਨ ਚੈੱਕਆਉਟ ਅਤੇ ਖਾਤਾ ਮਿਲਾਨ ਯੋਗ ਹੁੰਦੇ ਹਨ। ਦੇਰੀ ਨਾਲ ਖਾਤਾ ਬਣਾਉਣ ਨੂੰ ਕੌਂਫਿਗਰ ਕਰਨ ਲਈ ਉੱਪਰ ਦਿੱਤੀਆਂ ਦੋਵੇਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ।','Enable delayed account creation' => 'ਦੇਰੀ ਨਾਲ ਖਾਤਾ ਬਣਾਉਣਾ ਸਮਰੱਥ ਬਣਾਓ','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'ਜਦੋਂ ਮਹਿਮਾਨ ਚੈੱਕਆਉਟ ਅਤੇ ਖਾਤਾ ਮਿਲਾਨ ਦੋਵੇਂ ਸਮਰੱਥ ਹੋਣ ਤਾਂ ਦੇਰੀ ਨਾਲ ਖਾਤਾ ਬਣਾਉਣਾ ਸਮਰੱਥ ਬਣਾਓ।','Section position' => 'ਸੈਕਸ਼ਨ ਸਥਿਤੀ','Before customer details section' => 'ਗਾਹਕ ਵੇਰਵੇ ਭਾਗ ਤੋਂ ਪਹਿਲਾਂ','After customer details section' => 'ਗਾਹਕ ਵੇਰਵੇ ਵਾਲੇ ਭਾਗ ਤੋਂ ਬਾਅਦ','Account creation benefits' => 'ਖਾਤਾ ਬਣਾਉਣ ਦੇ ਲਾਭ','Leaving the field empty will display the default text.' => 'ਖੇਤਰ ਨੂੰ ਖਾਲੀ ਛੱਡਣ ਨਾਲ ਡਿਫਾਲਟ ਟੈਕਸਟ ਪ੍ਰਦਰਸ਼ਿਤ ਹੋਵੇਗਾ।','Inline buttons' => 'ਇਨਲਾਈਨ ਬਟਨ','Required fields' => 'ਲੋੜੀਂਦੇ ਖੇਤਰ','Enable gift message fields at checkout' => 'ਚੈੱਕਆਉਟ &#39;ਤੇ ਤੋਹਫ਼ੇ ਦੇ ਸੁਨੇਹੇ ਵਾਲੇ ਖੇਤਰਾਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Expanded gift message' => 'ਵਿਸਤ੍ਰਿਤ ਤੋਹਫ਼ਾ ਸੁਨੇਹਾ','Display gift message field always expanded' => 'ਡਿਸਪਲੇ ਤੋਹਫ਼ਾ ਸੁਨੇਹਾ ਖੇਤਰ ਹਮੇਸ਼ਾ ਫੈਲਾਇਆ ਜਾਂਦਾ ਹੈ','Gift message in order details' => 'ਆਰਡਰ ਵੇਰਵਿਆਂ ਵਿੱਚ ਤੋਹਫ਼ੇ ਦਾ ਸੁਨੇਹਾ','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ਇਸ ਭਾਗ ਵਿੱਚ ਇਸ ਵੇਲੇ ਕੋਈ ਏਕੀਕਰਨ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਹਰੇਕ ਪਲੱਗਇਨ ਅਤੇ ਥੀਮ ਨਾਲ ਸਬੰਧਤ ਵਿਕਲਪ ਇੱਥੇ ਸਿਰਫ਼ ਉਦੋਂ ਹੀ ਦਿਖਾਈ ਦੇਣਗੇ ਜਦੋਂ ਉਹ ਪਲੱਗਇਨ ਜਾਂ ਥੀਮ ਕਿਰਿਆਸ਼ੀਲ ਹੁੰਦਾ ਹੈ।','Phone fields' => 'ਫ਼ੋਨ ਖੇਤਰ','Field visibility' => 'ਖੇਤਰ ਦੀ ਦਿੱਖ','Field position' => 'ਫੀਲਡ ਸਥਿਤੀ','Phone country code & validation' => 'ਫ਼ੋਨ ਦੇਸ਼ ਕੋਡ ਅਤੇ ਪ੍ਰਮਾਣਿਕਤਾ','Country' => 'ਦੇਸ਼','Enable country on phone fields' => 'ਫ਼ੋਨ ਖੇਤਰਾਂ ਵਿੱਚ ਦੇਸ਼ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Filter countries for shipping or billing' => 'ਸ਼ਿਪਿੰਗ ਜਾਂ ਬਿਲਿੰਗ ਲਈ ਦੇਸ਼ਾਂ ਨੂੰ ਫਿਲਟਰ ਕਰੋ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ਹਰੇਕ ਫ਼ੋਨ ਖੇਤਰ &#39;ਤੇ ਦੇਸ਼ ਚੋਣਕਾਰ ਨੂੰ ਤੁਹਾਡੇ ਸਟੋਰ &#39;ਤੇ ਸ਼ਿਪਿੰਗ ਜਾਂ ਬਿਲਿੰਗ ਲਈ ਆਗਿਆ ਦਿੱਤੇ ਦੇਸ਼ਾਂ ਤੱਕ ਸੀਮਤ ਕਰੋ।','Validation' => 'ਪ੍ਰਮਾਣਿਕਤਾ','Enable simple validation based on country rules' => 'ਦੇਸ਼ ਦੇ ਨਿਯਮਾਂ ਦੇ ਆਧਾਰ &#39;ਤੇ ਸਧਾਰਨ ਪ੍ਰਮਾਣਿਕਤਾ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','Checks that the phone number is valid for the selected country, including country code and length.' => 'ਜਾਂਚ ਕਰਦਾ ਹੈ ਕਿ ਫ਼ੋਨ ਨੰਬਰ ਚੁਣੇ ਹੋਏ ਦੇਸ਼ ਲਈ ਵੈਧ ਹੈ, ਜਿਸ ਵਿੱਚ ਦੇਸ਼ ਦਾ ਕੋਡ ਅਤੇ ਲੰਬਾਈ ਸ਼ਾਮਲ ਹੈ।','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ਸਖ਼ਤੀ ਨਾਲ ਜਾਂਚ ਕਰੋ ਕਿ ਨੰਬਰ ਚੁਣੇ ਹੋਏ ਦੇਸ਼ ਲਈ ਇੱਕ ਵੈਧ ਮੋਬਾਈਲ, ਫਿਕਸਡ ਲਾਈਨ, ਜਾਂ ਹੋਰ ਸਵੀਕਾਰਯੋਗ ਕਿਸਮ ਹੈ। ਕੁਝ ਵੈਧ ਨੰਬਰਾਂ ਨੂੰ ਅਸਵੀਕਾਰ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।','Validation types' => 'ਪ੍ਰਮਾਣਿਕਤਾ ਦੀਆਂ ਕਿਸਮਾਂ','Placeholders' => 'ਪਲੇਸਹੋਲਡਰ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'ਇਸ ਵੇਲੇ ਪ੍ਰਬੰਧਨ ਲਈ ਕੋਈ ਲਾਇਸੈਂਸ ਕੁੰਜੀਆਂ ਨਹੀਂ ਹਨ। ਲਾਇਸੈਂਸ ਕੁੰਜੀਆਂ ਇੱਥੇ ਉਦੋਂ ਦਿਖਾਈ ਦੇਣਗੀਆਂ ਜਦੋਂ ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਪਲੱਗਇਨ ਜਾਂ ਐਡ-ਆਨ ਕਿਰਿਆਸ਼ੀਲ ਹੋਵੇਗਾ।','Default delivery type' => 'ਡਿਲੀਵਰੀ ਦੀ ਪੂਰਵ-ਨਿਰਧਾਰਤ ਕਿਸਮ','Choose which delivery type will be selected by default.' => 'ਚੁਣੋ ਕਿ ਡਿਲੀਵਰੀ ਦੀ ਕਿਹੜੀ ਕਿਸਮ ਡਿਫਾਲਟ ਤੌਰ &#39;ਤੇ ਚੁਣੀ ਜਾਵੇਗੀ।','Shipping zone fields' => 'ਸ਼ਿਪਿੰਗ ਜ਼ੋਨ ਖੇਤਰ','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ਸਥਾਨਕ ਪਿਕਅੱਪ ਸ਼ਿਪਿੰਗ ਜ਼ੋਨ ਫਿਲਟਰ ਖੇਤਰਾਂ ਲਈ ਕਿਹੜੇ ਖੇਤਰ ਪ੍ਰਦਰਸ਼ਿਤ ਕੀਤੇ ਜਾਣਗੇ, ਚੁਣੋ। ਸਾਰੇ ਉਪਲਬਧ ਵਿਕਲਪ ਦਿਖਾਉਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ਇਹ ਖੇਤਰ ਸਥਾਨਕ ਪਿਕਅੱਪ ਸ਼ਿਪਿੰਗ ਤਰੀਕਿਆਂ ਲਈ ਇੱਕ ਫਿਲਟਰ ਵਜੋਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕੀਤੇ ਜਾਣਗੇ। ਕੁਝ ਖੇਤਰ ਚੈੱਕਆਉਟ &#39;ਤੇ ਅਜੇ ਵੀ ਦਿਖਾਈ ਦੇ ਸਕਦੇ ਹਨ ਜਦੋਂ ਇੱਥੇ ਨਹੀਂ ਚੁਣੇ ਜਾਂਦੇ, ਜੇਕਰ ਅਨੁਕੂਲ ਪਲੱਗਇਨਾਂ ਨੂੰ ਉਹਨਾਂ ਨੂੰ ਸਹੀ ਢੰਗ ਨਾਲ ਕੰਮ ਕਰਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।','Order shipping address' => 'ਆਰਡਰ ਭੇਜਣ ਦਾ ਪਤਾ','Order pay page optimization' => 'ਆਰਡਰ ਪੇਅ ਪੇਜ ਔਪਟੀਮਾਈਜੇਸ਼ਨ','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ਅਦਾਇਗੀ ਨਾ ਕੀਤੇ ਆਰਡਰਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਵਾਂਗ ਹੀ ਸਪਸ਼ਟ, ਪਰਿਵਰਤਨ-ਕੇਂਦ੍ਰਿਤ ਲੇਆਉਟ ਦਿਓ।','Optimize the layout of the order pay page for orders pending payment.' => 'ਆਰਡਰ ਪੇਮੈਂਟ ਪੰਨੇ ਦੇ ਲੇਆਉਟ ਨੂੰ ਅਨੁਕੂਲ ਬਣਾਓ ਜੋ ਆਰਡਰਾਂ ਦੇ ਲੰਬਿਤ ਭੁਗਤਾਨ ਲਈ ਹਨ।','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ਇਕਸਾਰ ਖਰੀਦ ਯਾਤਰਾ ਲਈ ਆਰਡਰ ਭੁਗਤਾਨ ਅਨੁਭਵ ਨੂੰ ਆਪਣੇ ਚੈੱਕਆਉਟ ਨਾਲ ਮੇਲ ਕਰੋ।','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ਭਰੋਸੇ ਦੇ ਚਿੰਨ੍ਹ ਅਤੇ ਬੈਜ ਸ਼ਾਮਲ ਕਰੋ ਜਿੱਥੇ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਭੁਗਤਾਨ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਭਰੋਸਾ ਦੇਣ ਦੀ ਲੋੜ ਹੋਵੇ।','Thank you page optimization' => 'ਪੰਨਾ ਅਨੁਕੂਲਨ ਲਈ ਧੰਨਵਾਦ','Make the thank you page and order details clearer for customers after they buy.' => 'ਗਾਹਕਾਂ ਦੇ ਖਰੀਦਣ ਤੋਂ ਬਾਅਦ ਧੰਨਵਾਦ ਪੰਨੇ ਅਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਨੂੰ ਸਪਸ਼ਟ ਬਣਾਓ।','Optimize the thank you page and account order details with a clearer layout.' => 'ਧੰਨਵਾਦ ਪੰਨੇ ਅਤੇ ਖਾਤੇ ਦੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਨੂੰ ਇੱਕ ਸਪਸ਼ਟ ਲੇਆਉਟ ਨਾਲ ਅਨੁਕੂਲ ਬਣਾਓ।','Show order status progress, actions, downloads, and notes where they make sense.' => 'ਆਰਡਰ ਸਥਿਤੀ ਦੀ ਪ੍ਰਗਤੀ, ਕਾਰਵਾਈਆਂ, ਡਾਊਨਲੋਡ ਅਤੇ ਨੋਟਸ ਦਿਖਾਓ ਜਿੱਥੇ ਉਹ ਸਮਝ ਵਿੱਚ ਆਉਣ।','Customize order details sections on email notifications.' => 'ਈਮੇਲ ਸੂਚਨਾਵਾਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਵਾਲੇ ਭਾਗਾਂ ਨੂੰ ਅਨੁਕੂਲਿਤ ਕਰੋ।','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ਜਿੱਥੇ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਖਰੀਦਦਾਰੀ ਤੋਂ ਬਾਅਦ ਭਰੋਸੇ ਦੀ ਲੋੜ ਹੋਵੇ, ਉੱਥੇ ਵਿਸ਼ਵਾਸ ਚਿੰਨ੍ਹ ਅਤੇ ਬੈਜ ਸ਼ਾਮਲ ਕਰੋ।','Email notifications' => 'ਈਮੇਲ ਸੂਚਨਾਵਾਂ','Enable thank you page and order details optimizations to see more options' => 'ਹੋਰ ਵਿਕਲਪ ਦੇਖਣ ਲਈ ਧੰਨਵਾਦ ਪੰਨੇ ਅਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ ਦੇ ਅਨੁਕੂਲਨ ਨੂੰ ਚਾਲੂ ਕਰੋ','Use wide layout on thank you page' => 'ਧੰਨਵਾਦ ਪੰਨੇ &#39;ਤੇ ਚੌੜਾ ਲੇਆਉਟ ਵਰਤੋ','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ਇਹ ਵਿਕਲਪ ਧੰਨਵਾਦ ਪੰਨੇ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ, ਖਾਤੇ ਦੇ ਪੰਨਿਆਂ ਅਤੇ ਈਮੇਲ ਸੂਚਨਾਵਾਂ &#39;ਤੇ ਆਰਡਰ ਵੇਰਵੇ ਵੇਖੋ।','Save settings' => 'ਸੈਟਿੰਗਾਂ ਸੇਵ ਕਰੋ','Docs' => 'ਡੌਕਸ','Cart' => 'ਕਾਰਟ','Thank you' => 'ਤੁਹਾਡਾ ਧੰਨਵਾਦ','Address autocomplete' => 'ਪਤਾ ਸਵੈ-ਮੁਕੰਮਲ','Trust badges' => 'ਟਰੱਸਟ ਬੈਜ','You do not have permission to save these settings.' => 'ਤੁਹਾਡੇ ਕੋਲ ਇਹਨਾਂ ਸੈਟਿੰਗਾਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।','Invalid save request.' => 'ਅਵੈਧ ਸੇਵ ਬੇਨਤੀ।','Your settings have been saved.' => 'ਤੁਹਾਡੀਆਂ ਸੈਟਿੰਗਾਂ ਸੁਰੱਖਿਅਤ ਕਰ ਲਈਆਂ ਗਈਆਂ ਹਨ।','Saving...' => 'ਸੇਵ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...','Settings could not be saved. Please try again.' => 'ਸੈਟਿੰਗਾਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Dismiss notice' => 'ਨੋਟਿਸ ਖਾਰਜ ਕਰੋ','Open settings menu' => 'ਸੈਟਿੰਗਾਂ ਮੀਨੂ ਖੋਲ੍ਹੋ','Close settings menu' => 'ਸੈਟਿੰਗਾਂ ਮੀਨੂ ਬੰਦ ਕਰੋ','Preview' => 'ਝਲਕ','Expand preview' => 'ਪੂਰਵਦਰਸ਼ਨ ਦਾ ਵਿਸਤਾਰ ਕਰੋ','Collapse preview' => 'ਪੂਰਵਦਰਸ਼ਨ ਨੂੰ ਸਮੇਟੋ','Show header and footer' => 'ਹੈਡਰ ਅਤੇ ਫੁੱਟਰ ਦਿਖਾਓ','Hide header and footer' => 'ਹੈਡਰ ਅਤੇ ਫੁੱਟਰ ਲੁਕਾਓ','Page preview' => 'ਪੰਨਾ ਪੂਰਵਦਰਸ਼ਨ','Preview viewport' => 'ਵਿਊਪੋਰਟ ਦੀ ਝਲਕ ਦੇਖੋ','Tablet' => 'ਟੈਬਲੇਟ','Desktop' => 'ਡੈਸਕਟਾਪ','Preview width' => 'ਪੂਰਵਦਰਸ਼ਨ ਚੌੜਾਈ','Decrease width' => 'ਚੌੜਾਈ ਘਟਾਓ','Preview width in pixels' => 'ਪਿਕਸਲਾਂ ਵਿੱਚ ਚੌੜਾਈ ਦੀ ਝਲਕ ਦੇਖੋ','Increase width' => 'ਚੌੜਾਈ ਵਧਾਓ','Preview as' => 'ਇਸ ਤਰ੍ਹਾਂ ਪੂਰਵਦਰਸ਼ਨ ਕਰੋ','Guest' => 'ਮਹਿਮਾਨ','Logged in' => 'ਲੌਗਇਨ ਕੀਤਾ','Preview page' => 'ਪੂਰਵਦਰਸ਼ਨ ਪੰਨਾ','Expand preview for a closer look' => 'ਨੇੜਿਓਂ ਦੇਖਣ ਲਈ ਪੂਰਵਦਰਸ਼ਨ ਦਾ ਵਿਸਤਾਰ ਕਰੋ','Available with %s.' => '%s ਨਾਲ ਉਪਲਬਧ।','Turn them on' => 'ਉਹਨਾਂ ਨੂੰ ਚਾਲੂ ਕਰੋ','Optimizations for this page are turned off. %s to preview the page.' => 'ਇਸ ਪੰਨੇ ਲਈ ਅਨੁਕੂਲਤਾ ਬੰਦ ਹਨ। ਪੰਨੇ ਦੀ ਝਲਕ ਦੇਖਣ ਲਈ %s।','%s preview' => '%s ਪੂਰਵਦਰਸ਼ਨ','Isolated session · nothing is saved' => 'ਇਕੱਲਾ ਸੈਸ਼ਨ · ਕੁਝ ਵੀ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ','Usage tracking' => 'ਵਰਤੋਂ ਟਰੈਕਿੰਗ','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨੂੰ ਅਨੁਕੂਲਤਾ ਵਿੱਚ ਸੁਧਾਰ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਗੈਰ-ਸੰਵੇਦਨਸ਼ੀਲ ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਾਂ ਭੇਜੋ। ਹੇਠਾਂ ਦਿੱਤੇ ਵਿਕਲਪਾਂ ਵਿੱਚ ਸਮਰੱਥ ਹੋਣ ਤੱਕ ਰਿਪੋਰਟਾਂ ਨਹੀਂ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ।','Send usage tracking reports to Fluid Checkout' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨੂੰ ਵਰਤੋਂ ਟਰੈਕਿੰਗ ਰਿਪੋਰਟਾਂ ਭੇਜੋ','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'ਇਹ ਰਿਪੋਰਟਾਂ ਤੁਹਾਡੀ ਸਾਈਟ ਲਈ ਅਨੁਕੂਲਤਾ ਅਤੇ ਸਹਾਇਤਾ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰਦੀਆਂ ਹਨ ਅਤੇ ਚਾਲੂ ਹੋਣ &#39;ਤੇ ਹਫ਼ਤਾਵਾਰੀ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।','No customer, admin user, or any other sensitive data is included in the reports.' => 'ਰਿਪੋਰਟਾਂ ਵਿੱਚ ਕੋਈ ਵੀ ਗਾਹਕ, ਐਡਮਿਨ ਉਪਭੋਗਤਾ, ਜਾਂ ਕੋਈ ਹੋਰ ਸੰਵੇਦਨਸ਼ੀਲ ਡੇਟਾ ਸ਼ਾਮਲ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ।','Basic environment info' => 'ਮੁੱਢਲੀ ਵਾਤਾਵਰਣ ਜਾਣਕਾਰੀ','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'ਵਰਡਪ੍ਰੈਸ, PHP, WooCommerce, ਥੀਮ, ਅਤੇ ਪਲੱਗਇਨ ਸੂਚੀ ਡੇਟਾ। ਰਿਪੋਰਟਿੰਗ ਸਮਰੱਥ ਹੋਣ &#39;ਤੇ ਹਮੇਸ਼ਾਂ ਸ਼ਾਮਲ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਸਾਨੂੰ ਇਹ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ ਕਿ ਤੁਹਾਡੀ ਸਾਈਟ ਕਿਸ ਵਾਤਾਵਰਣ ਵਿੱਚ ਚੱਲ ਰਹੀ ਹੈ।','Plugin settings' => 'ਪਲੱਗਇਨ ਸੈਟਿੰਗਾਂ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'ਸਹਾਇਤਾ ਬੇਨਤੀਆਂ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਪਲੱਗਇਨ ਸੈਟਿੰਗਾਂ ਭੇਜਦਾ ਹੈ ਅਤੇ ਸਾਨੂੰ ਇਹ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਸਾਡੇ ਪਲੱਗਇਨ ਕਿਵੇਂ ਵਰਤ ਰਹੇ ਹੋ।','Coming soon' => 'ਆਨ ਵਾਲੀ','Sales metrics' => 'ਵਿਕਰੀ ਮੈਟ੍ਰਿਕਸ','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਸਥਾਪਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਸਾਲ ਲਈ ਮਾਸਿਕ ਆਰਡਰ ਗਿਣਤੀ ਅਤੇ ਅੱਜ ਤੱਕ ਦੀ ਕੁੱਲ ਵਿਕਰੀ। ਸਾਨੂੰ ਇਹ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ ਕਿ ਕੀ ਤੁਸੀਂ ਸਾਡੇ ਪਲੱਗਇਨ ਸਥਾਪਤ ਕਰਕੇ ਵਧੇਰੇ ਪੈਸਾ ਕਮਾ ਰਹੇ ਹੋ। ਕੋਈ ਵੀ ਗਾਹਕ ਜਾਂ ਉਪਭੋਗਤਾ ਡੇਟਾ ਕਦੇ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ ਹੈ।','Utilities' => 'ਸਹੂਲਤਾਂ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ਦੀ ਬਜਾਏ <code>TomSelect</code> ਡ੍ਰੌਪਡਾਉਨ ਕੰਪੋਨੈਂਟਸ ਦੀ ਵਰਤੋਂ ਕਰੋ।','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'ਟੌਮਸਿਲੈਕਟ ਇੱਕ ਸਰਲ ਡ੍ਰੌਪਡਾਉਨ ਚੋਣ ਕੰਪੋਨੈਂਟ ਹੈ ਜੋ Select2 ਨਾਲੋਂ ਘੱਟ ਗਲਤੀਆਂ ਦਾ ਸ਼ਿਕਾਰ ਹੈ, ਜਦੋਂ ਕਿ ਇਹ ਉਹੀ ਕਾਰਜਸ਼ੀਲਤਾ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ।','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'ਛੋਟੇ ਡਿਵਾਈਸਾਂ &#39;ਤੇ ਫਾਰਮ ਫੀਲਡਾਂ ਨਾਲ ਇੰਟਰੈਕਟ ਕਰਦੇ ਸਮੇਂ ਆਪਣੇ ਆਪ ਜ਼ੂਮ ਇਨ ਹੋਣ ਤੋਂ ਬਚਣ ਲਈ ਇਸ ਪਲੱਗਇਨ ਦੁਆਰਾ ਅਨੁਕੂਲਿਤ ਪੰਨਿਆਂ &#39;ਤੇ ਫਾਰਮ ਫੀਲਡਾਂ ਦੇ ਅੰਦਰ ਫੌਂਟ ਆਕਾਰ ਨੂੰ 16px &#39;ਤੇ ਸੈੱਟ ਕਰਦਾ ਹੈ।','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ਜਦੋਂ ਫੌਂਟ ਦਾ ਆਕਾਰ 16px ਤੋਂ ਛੋਟਾ ਹੁੰਦਾ ਹੈ ਤਾਂ ਟੈਕਸਟ ਨੂੰ ਪੜ੍ਹਨਾ ਆਸਾਨ ਬਣਾਉਣ ਲਈ ਸਫਾਰੀ ਅਤੇ ਹੋਰ ਬ੍ਰਾਊਜ਼ਰ ਮੋਬਾਈਲ ਡਿਵਾਈਸਾਂ &#39;ਤੇ ਆਪਣੇ ਆਪ ਜ਼ੂਮ ਇਨ ਕਰ ਸਕਦੇ ਹਨ।','Enable script processing tracking on the browser console.' => 'ਬ੍ਰਾਊਜ਼ਰ ਕੰਸੋਲ &#39;ਤੇ ਸਕ੍ਰਿਪਟ ਪ੍ਰੋਸੈਸਿੰਗ ਟਰੈਕਿੰਗ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ।','Unminified assets' => 'ਅਣ-ਨਿਰਮਿਤ ਸੰਪਤੀਆਂ','Google Maps scripts' => 'ਗੂਗਲ ਮੈਪਸ ਸਕ੍ਰਿਪਟਾਂ','Do not remove duplicate Google Maps scripts' => 'ਡੁਪਲੀਕੇਟ Google ਨਕਸ਼ੇ ਸਕ੍ਰਿਪਟਾਂ ਨੂੰ ਨਾ ਹਟਾਓ','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'ਜਦੋਂ ਸਮਰੱਥ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਡੁਪਲੀਕੇਟ Google ਨਕਸ਼ੇ ਸਕ੍ਰਿਪਟਾਂ ਨੂੰ ਨਹੀਂ ਹਟਾਇਆ ਜਾਵੇਗਾ ਜਿਸ ਕਾਰਨ ਗਲਤੀਆਂ ਅਤੇ ਪ੍ਰਦਰਸ਼ਨ ਸਮੱਸਿਆਵਾਂ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਸਮੱਸਿਆ ਦਾ ਨਿਪਟਾਰਾ ਕਰਦੇ ਸਮੇਂ ਹੀ ਇਸ ਵਿਕਲਪ ਦੀ ਵਰਤੋਂ ਕਰੋ।','Widget areas' => 'ਵਿਜੇਟ ਖੇਤਰ','Last step on mobile' => 'ਮੋਬਾਈਲ &#39;ਤੇ ਆਖਰੀ ਕਦਮ','Display widgets only at last step on mobile' => 'ਮੋਬਾਈਲ &#39;ਤੇ ਸਿਰਫ਼ ਆਖਰੀ ਪੜਾਅ &#39;ਤੇ ਵਿਜੇਟਸ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'ਮੋਬਾਈਲ ਡੀਵਾਈਸਾਂ &#39;ਤੇ ਆਖਰੀ ਚੈੱਕਆਉਟ ਪੜਾਅ ਦੇਖਣ ਵੇਲੇ ਹੀ ਚੈੱਕਆਉਟ ਟਰੱਸਟ ਬੈਜ ਵਿਜੇਟ ਦਿਖਾਓ','Standard' => 'ਮਿਆਰੀ','VAT number field' => 'ਵੈਟ ਨੰਬਰ ਖੇਤਰ','Add a VAT number field to the billing form.' => 'ਬਿਲਿੰਗ ਫਾਰਮ ਵਿੱਚ ਇੱਕ VAT ਨੰਬਰ ਖੇਤਰ ਸ਼ਾਮਲ ਕਰੋ।','Field label' => 'ਫੀਲਡ ਲੇਬਲ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT ਨੰਬਰ ਖੇਤਰ (ਭਾਵ VAT ਨੰਬਰ) ਦਾ ਲੇਬਲ ਸੈੱਟ ਕਰੋ। ਬਹੁ-ਭਾਸ਼ਾਈ ਵੈੱਬਸਾਈਟਾਂ &#39;ਤੇ, ਇਸ ਖੇਤਰ ਨੂੰ ਖਾਲੀ ਛੱਡਣਾ ਅਤੇ ਮੂਲ ਸਤਰ ਦਾ ਅਨੁਵਾਦ ਕਰਨਾ ਬਿਹਤਰ ਹੈ।','VAT Number' => 'ਵੈਟ ਨੰਬਰ','EU-VAT' => 'ਈਯੂ-ਵੈਟ','Enable the VAT number field to see more options' => 'ਹੋਰ ਵਿਕਲਪ ਦੇਖਣ ਲਈ VAT ਨੰਬਰ ਖੇਤਰ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ','VAT validation' => 'ਵੈਟ ਪ੍ਰਮਾਣਿਕਤਾ','Validate VAT number field for EU-VAT during checkout' => 'ਚੈੱਕਆਉਟ ਦੌਰਾਨ EU-VAT ਲਈ VAT ਨੰਬਰ ਖੇਤਰ ਨੂੰ ਪ੍ਰਮਾਣਿਤ ਕਰੋ','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'ਜਾਂਚ ਕਰਦਾ ਹੈ ਕਿ ਕੀ ਦਿੱਤਾ ਗਿਆ VAT ਨੰਬਰ ਯੂਰਪੀਅਨ VIES ਡੇਟਾਬੇਸ (VAT ਇਨਫਰਮੇਸ਼ਨ ਐਕਸਚੇਂਜ ਸਿਸਟਮ) &#39;ਤੇ ਰਜਿਸਟਰਡ ਇੱਕ ਵੈਧ VAT ਨੰਬਰ ਹੈ।','Shop VAT number' => 'ਦੁਕਾਨ ਦਾ ਵੈਟ ਨੰਬਰ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ਦੁਕਾਨ ਦਾ VAT ਨੰਬਰ ਜੋ EU-VAT ਪ੍ਰਮਾਣਿਕਤਾ ਦੀ ਬੇਨਤੀ ਕਰਨ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਇਨਵੌਇਸਾਂ &#39;ਤੇ ਛਾਪਿਆ ਜਾਂਦਾ ਹੈ।<br> <strong>ਅਸੀਂ ਜ਼ੋਰਦਾਰ ਸਿਫਾਰਸ਼ ਕਰਦੇ ਹਾਂ ਕਿ ਤੁਸੀਂ ਆਪਣਾ ਦੁਕਾਨ ਵੈਟ ਨੰਬਰ ਸ਼ਾਮਲ ਕਰੋ</strong> ਕਿਉਂਕਿ ਨਹੀਂ ਤਾਂ VIES ਸਲਾਹ-ਮਸ਼ਵਰੇ ਦੇ ਨਤੀਜੇ ਲੇਖਾਕਾਰੀ ਉਦੇਸ਼ਾਂ ਲਈ ਵੈਧ ਨਹੀਂ ਹੋ ਸਕਦੇ।<br> ਭਾਵ: <code>ATU99999999</code> ਜਾਂ <code>EE999999999</code> ।','Reverse charge' => 'ਰਿਵਰਸ ਚਾਰਜ','Apply reverse charge mechanism' => 'ਰਿਵਰਸ ਚਾਰਜ ਵਿਧੀ ਲਾਗੂ ਕਰੋ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'ਟੈਕਸ ਦਰ ਨੂੰ ਜ਼ੀਰੋ &#39;ਤੇ ਸੈੱਟ ਕਰੋ ਅਤੇ ਗਾਹਕ ਦਾ VAT ਨੰਬਰ ਵੈਧ ਹੋਣ &#39;ਤੇ ਇਨਵੌਇਸਾਂ &#39;ਤੇ &quot;ਰਿਵਰਸ ਚਾਰਜ&quot; ਪ੍ਰਦਰਸ਼ਿਤ ਕਰੋ। ਸਟੋਰ ਦੇ ਦੇਸ਼ ਦੇ ਆਧਾਰ &#39;ਤੇ ਇੱਕ ਵੱਖਰਾ &quot;ਰਿਵਰਸ ਚਾਰਜ&quot; ਟੈਕਸਟ ਲੋੜੀਂਦਾ ਹੋ ਸਕਦਾ ਹੈ।','Same country' => 'ਉਹੀ ਦੇਸ਼','Apply reverse charge mechanism for transactions in the shop country:' => 'ਦੁਕਾਨ ਵਾਲੇ ਦੇਸ਼ ਵਿੱਚ ਲੈਣ-ਦੇਣ ਲਈ ਰਿਵਰਸ ਚਾਰਜ ਵਿਧੀ ਲਾਗੂ ਕਰੋ:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'ਦੁਕਾਨ ਵਾਲੇ ਦੇਸ਼ ਵਿੱਚ ਕੰਪਨੀਆਂ ਵਿਚਕਾਰ ਲੈਣ-ਦੇਣ ਲਈ ਰਿਵਰਸ ਚਾਰਜ ਵਿਧੀ ਲਾਗੂ ਕਰਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਂਦਾ ਹੈ।','Reverse charge exceptions' => 'ਰਿਵਰਸ ਚਾਰਜ ਅਪਵਾਦ','Select additional countries to skip applying the reverse charge mechanism.' => 'ਰਿਵਰਸ ਚਾਰਜ ਵਿਧੀ ਨੂੰ ਲਾਗੂ ਕਰਨ ਤੋਂ ਬਚਣ ਲਈ ਵਾਧੂ ਦੇਸ਼ ਚੁਣੋ।','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'ਇਹਨਾਂ ਦੇਸ਼ਾਂ ਤੋਂ ਆਉਣ ਵਾਲੇ ਆਰਡਰਾਂ &#39;ਤੇ ਟੈਕਸ ਲਏ ਜਾਣਗੇ ਭਾਵੇਂ ਇੱਕ ਵੈਧ ਵੈਟ ਨੰਬਰ ਦਿੱਤਾ ਗਿਆ ਹੋਵੇ।','Reverse charge label on invoices' => 'ਇਨਵੌਇਸਾਂ &#39;ਤੇ ਚਾਰਜ ਲੇਬਲ ਉਲਟਾਓ','Set the label of "reverse charge" on the checkout page and order details.' => 'ਚੈੱਕਆਉਟ ਪੰਨੇ ਅਤੇ ਆਰਡਰ ਵੇਰਵਿਆਂ &#39;ਤੇ &quot;ਰਿਵਰਸ ਚਾਰਜ&quot; ਦਾ ਲੇਬਲ ਸੈੱਟ ਕਰੋ।','Reverse charge text on invoices' => 'ਇਨਵੌਇਸਾਂ &#39;ਤੇ ਰਿਵਰਸ ਚਾਰਜ ਟੈਕਸਟ','Set the label of "reverse charge" text on invoices.' => 'ਇਨਵੌਇਸਾਂ &#39;ਤੇ &quot;ਰਿਵਰਸ ਚਾਰਜ&quot; ਟੈਕਸਟ ਦਾ ਲੇਬਲ ਸੈੱਟ ਕਰੋ।','Tax to be paid on reverse charge basis' => 'ਰਿਵਰਸ ਚਾਰਜ ਦੇ ਆਧਾਰ &#39;ਤੇ ਟੈਕਸ ਦਾ ਭੁਗਤਾਨ ਕੀਤਾ ਜਾਣਾ ਹੈ','Company name' => 'ਕੰਪਨੀ ਦਾ ਨਾਂ','Autocomplete company name from VAT number' => 'VAT ਨੰਬਰ ਤੋਂ ਕੰਪਨੀ ਦਾ ਨਾਮ ਸਵੈ-ਮੁਕੰਮਲ ਕਰੋ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ਗਾਹਕ ਦੁਆਰਾ ਪ੍ਰਦਾਨ ਕੀਤੇ ਗਏ ਵੈਧ ਵੈਟ ਨੰਬਰ ਦੇ ਆਧਾਰ &#39;ਤੇ ਬਿਲਿੰਗ ਕੰਪਨੀ ਦਾ ਨਾਮ ਭਰੋ।','Company name editing' => 'ਕੰਪਨੀ ਦੇ ਨਾਮ ਦਾ ਸੰਪਾਦਨ','Allow editing of auto-filled company name' => 'ਆਟੋ-ਭਰੇ ਕੰਪਨੀ ਦੇ ਨਾਮ ਦੇ ਸੰਪਾਦਨ ਦੀ ਆਗਿਆ ਦਿਓ','When enabled, customers can change the company name associated with the provided VAT number.' => 'ਜਦੋਂ ਸਮਰੱਥ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਗਾਹਕ ਦਿੱਤੇ ਗਏ ਵੈਟ ਨੰਬਰ ਨਾਲ ਜੁੜੇ ਕੰਪਨੀ ਦੇ ਨਾਮ ਨੂੰ ਬਦਲ ਸਕਦੇ ਹਨ।','EU-VAT for digital goods' => 'ਡਿਜੀਟਲ ਸਾਮਾਨ ਲਈ EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '1 ਜਨਵਰੀ, 2015 ਤੋਂ, ਡਿਜੀਟਲ ਸਾਮਾਨ ਸੰਬੰਧੀ EU VAT ਨਿਯਮਾਂ ਵਿੱਚ ਸੋਧਾਂ ਕੀਤੀਆਂ ਗਈਆਂ ਹਨ, ਜੋ ਸਿਰਫ਼ B2C ਲੈਣ-ਦੇਣ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀਆਂ ਹਨ। ਡਿਜੀਟਲ ਸਾਮਾਨ &#39;ਤੇ ਵੈਟ ਦੀ ਗਣਨਾ ਗਾਹਕ ਦੇ ਸਥਾਨ ਦੇ ਆਧਾਰ &#39;ਤੇ ਕੀਤੀ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ, ਅਤੇ ਇਸ ਦੇ ਸਬੂਤ ਇਕੱਠੇ ਕਰਨ ਦੀ ਲੋੜ ਹੈ (IP ਪਤਾ ਅਤੇ ਬਿਲਿੰਗ ਪਤਾ)।','Tax classes for digital goods' => 'ਡਿਜੀਟਲ ਸਾਮਾਨ ਲਈ ਟੈਕਸ ਸ਼੍ਰੇਣੀਆਂ','Select some tax classes' => 'ਕੁਝ ਟੈਕਸ ਸ਼੍ਰੇਣੀਆਂ ਚੁਣੋ','Location evidence' => 'ਸਥਾਨ ਸਬੂਤ','Collect customer\'s location evidence' => 'ਗਾਹਕ ਦੇ ਸਥਾਨ ਦੇ ਸਬੂਤ ਇਕੱਠੇ ਕਰੋ','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP ਐਡਰੈੱਸ ਨੂੰ ਸੇਵ ਕਰਦਾ ਹੈ ਅਤੇ ਇਸਨੂੰ ਗਾਹਕ ਦੇ ਬਿਲਿੰਗ ਪਤੇ ਦੇ ਵਿਰੁੱਧ ਪ੍ਰਮਾਣਿਤ ਕਰਦਾ ਹੈ। ਜੇਕਰ ਗਾਹਕਾਂ ਦੇ ਬਿਲਿੰਗ ਪਤੇ ਅਤੇ IP ਤੋਂ ਦੇਸ਼ ਮੇਲ ਨਹੀਂ ਖਾਂਦਾ ਹੈ ਤਾਂ ਉਹਨਾਂ ਨੂੰ ਚੈੱਕਆਉਟ ਪੰਨੇ &#39;ਤੇ ਇੱਕ ਚੈੱਕਬਾਕਸ ਦੀ ਜਾਂਚ ਕਰਕੇ ਆਪਣੇ ਬਿਲਿੰਗ ਪਤੇ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ।','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ਇਹ ਵਿਕਲਪ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਵਿੱਚ ਪ੍ਰਬੰਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। <a href="%s">ਇਸਨੂੰ ਗਾਹਕ ਖਾਤੇ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਬਦਲੋ</a> ।','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ਇਹ ਵਿਕਲਪ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਵਿੱਚ ਪ੍ਰਬੰਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਇਸਨੂੰ ਫਲੂਇਡ ਚੈੱਕਆਉਟ &gt; ਗਾਹਕ ਖਾਤਿਆਂ ਦੇ ਅਧੀਨ ਬਦਲੋ।','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ਇਹ ਵਿਕਲਪ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਵਿੱਚ ਪ੍ਰਬੰਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਜਦੋਂ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਕਿਰਿਆਸ਼ੀਲ ਹੁੰਦਾ ਹੈ ਤਾਂ ਸ਼ਿਪਿੰਗ ਮੰਜ਼ਿਲ ਹਮੇਸ਼ਾਂ &quot;ਗਾਹਕ ਸ਼ਿਪਿੰਗ ਪਤੇ &#39;ਤੇ ਡਿਫਾਲਟ&quot; &#39;ਤੇ ਸੈੱਟ ਹੁੰਦੀ ਹੈ। ਗਾਹਕ ਅਜੇ ਵੀ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਵੱਖ-ਵੱਖ ਸ਼ਿਪਿੰਗ ਅਤੇ ਬਿਲਿੰਗ ਪਤੇ ਪ੍ਰਦਾਨ ਕਰ ਸਕਦੇ ਹਨ।<br><br> ਡਿਫੌਲਟ ਬਿਲਿੰਗ ਪਤੇ ਨੂੰ ਸ਼ਿਪਿੰਗ ਪਤੇ ਦੇ ਸਮਾਨ ਸੈੱਟ ਕਰਨ ਦਾ ਵਿਕਲਪ <a href="%s">ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਸੈਟਿੰਗਾਂ</a> ਵਿੱਚ ਉਪਲਬਧ ਹੈ।','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ਇਹ ਵਿਕਲਪ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਵਿੱਚ ਪ੍ਰਬੰਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਜਦੋਂ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਕਿਰਿਆਸ਼ੀਲ ਹੁੰਦਾ ਹੈ ਤਾਂ ਸ਼ਿਪਿੰਗ ਮੰਜ਼ਿਲ ਹਮੇਸ਼ਾਂ &quot;ਗਾਹਕ ਸ਼ਿਪਿੰਗ ਪਤੇ &#39;ਤੇ ਡਿਫਾਲਟ&quot; &#39;ਤੇ ਸੈੱਟ ਹੁੰਦੀ ਹੈ। ਗਾਹਕ ਅਜੇ ਵੀ ਚੈੱਕਆਉਟ ਦੌਰਾਨ ਵੱਖ-ਵੱਖ ਸ਼ਿਪਿੰਗ ਅਤੇ ਬਿਲਿੰਗ ਪਤੇ ਪ੍ਰਦਾਨ ਕਰ ਸਕਦੇ ਹਨ।<br><br> ਡਿਫੌਲਟ ਬਿਲਿੰਗ ਪਤੇ ਨੂੰ ਸ਼ਿਪਿੰਗ ਪਤੇ ਦੇ ਸਮਾਨ ਸੈੱਟ ਕਰਨ ਦਾ ਵਿਕਲਪ WooCommerce &gt; ਸੈਟਿੰਗਾਂ &gt; Fluid Checkout &#39;ਤੇ ਉਪਲਬਧ ਹੈ।','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ਇਹਨਾਂ ਸੈਟਿੰਗਾਂ ਨੂੰ WP ਐਡਮਿਨ &gt; ਫਲੂਇਡ ਚੈੱਕਆਉਟ &gt; ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਤਬਦੀਲ ਕਰ ਦਿੱਤਾ ਗਿਆ ਹੈ।','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ਇਹ WooCommerce ਸੈਟਿੰਗਜ਼ ਟੈਬ ਨਾਪਸੰਦ ਕੀਤਾ ਗਿਆ ਹੈ ਅਤੇ ਇਸਨੂੰ Fluid Checkout 6.0 ਵਿੱਚ ਹਟਾ ਦਿੱਤਾ ਜਾਵੇਗਾ।','Go to settings page' => 'ਸੈਟਿੰਗਾਂ ਪੰਨੇ &#39;ਤੇ ਜਾਓ','Hide this tab permanently' => 'ਇਸ ਟੈਬ ਨੂੰ ਪੱਕੇ ਤੌਰ &#39;ਤੇ ਲੁਕਾਓ','Site report preview' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਦੀ ਝਲਕ','This is the data that would be included in the next site environment report based on your current settings.' => 'ਇਹ ਉਹ ਡੇਟਾ ਹੈ ਜੋ ਤੁਹਾਡੀਆਂ ਮੌਜੂਦਾ ਸੈਟਿੰਗਾਂ ਦੇ ਆਧਾਰ &#39;ਤੇ ਅਗਲੀ ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟ ਵਿੱਚ ਸ਼ਾਮਲ ਕੀਤਾ ਜਾਵੇਗਾ।','Loading report preview...' => 'ਰਿਪੋਰਟ ਪ੍ਰੀਵਿਊ ਲੋਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ...','Could not load the site report preview. Try again.' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਪ੍ਰੀਵਿਊ ਲੋਡ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਿਆ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Could not send the site report. Try again.' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਨਹੀਂ ਭੇਜੀ ਜਾ ਸਕੀ। ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Site report sent successfully.' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਸਫਲਤਾਪੂਰਵਕ ਭੇਜੀ ਗਈ।','Enable and send now' => 'ਹੁਣੇ ਚਾਲੂ ਕਰੋ ਅਤੇ ਭੇਜੋ','Close' => 'ਬੰਦ ਕਰੋ','A site report request is already in progress. Try again in a moment.' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਬੇਨਤੀ ਪਹਿਲਾਂ ਹੀ ਪ੍ਰਗਤੀ ਅਧੀਨ ਹੈ। ਕੁਝ ਦੇਰ ਬਾਅਦ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Site environment reporting is disabled.' => 'ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਿੰਗ ਅਯੋਗ ਹੈ।','No site report data is available to send.' => 'ਭੇਜਣ ਲਈ ਕੋਈ ਸਾਈਟ ਰਿਪੋਰਟ ਡਾਟਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।','This site domain cannot send environment reports (local or development domains are excluded).' => 'ਇਹ ਸਾਈਟ ਡੋਮੇਨ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਾਂ ਨਹੀਂ ਭੇਜ ਸਕਦਾ (ਸਥਾਨਕ ਜਾਂ ਵਿਕਾਸ ਡੋਮੇਨ ਸ਼ਾਮਲ ਨਹੀਂ ਹਨ)।','A site report was sent recently. Try again later.' => 'ਹਾਲ ਹੀ ਵਿੱਚ ਇੱਕ ਸਾਈਟ ਰਿਪੋਰਟ ਭੇਜੀ ਗਈ ਸੀ। ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','The site report could not be sent. Try again later.' => 'ਸਾਈਟ ਰਿਪੋਰਟ ਭੇਜੀ ਨਹੀਂ ਜਾ ਸਕੀ। ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।','Site environment reporting is not available.' => 'ਸਾਈਟ ਵਾਤਾਵਰਣ ਰਿਪੋਰਟਿੰਗ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।','No site report data is available for the selected settings.' => 'ਚੁਣੀਆਂ ਗਈਆਂ ਸੈਟਿੰਗਾਂ ਲਈ ਕੋਈ ਸਾਈਟ ਰਿਪੋਰਟ ਡਾਟਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।','You are not allowed to manage site reports.' => 'ਤੁਹਾਨੂੰ ਸਾਈਟ ਰਿਪੋਰਟਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।','PRO feature' => 'ਪ੍ਰੋ ਵਿਸ਼ੇਸ਼ਤਾ','Other plugins' => 'ਹੋਰ ਪਲੱਗਇਨ','Get only this add-on &mdash; %s' => 'ਸਿਰਫ਼ ਇਹ ਐਡ-ਆਨ ਪ੍ਰਾਪਤ ਕਰੋ — %s','Install add-on' => 'ਐਡ-ਆਨ ਸਥਾਪਤ ਕਰੋ','Upgrade to PRO &mdash; %s' => 'PRO — %s ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'ਇਹਨਾਂ ਵਿਕਲਪਾਂ ਨੂੰ ਅਨਲੌਕ ਕਰਨ ਲਈ <a target="_blank" href="%1$s">%2$s ਪ੍ਰਾਪਤ ਕਰੋ</a> ।','Add-on' => 'ਹੋਰ ਜੋੜਨਾ','View documentation' => 'ਦਸਤਾਵੇਜ਼ ਵੇਖੋ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'ਬੇਨਤੀਆਂ ਲਈ ਇੱਕ ਲੌਗ-ਇਨ ਵਰਡਪ੍ਰੈਸ ਉਪਭੋਗਤਾ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਮੌਜੂਦਾ ਉਪਭੋਗਤਾ ਦੇ ਡੇਟਾ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ user_id ਨੂੰ ਛੱਡ ਦਿਓ, ਜਾਂ ਜਦੋਂ ਕਾਲਰ ਉਸ ਉਪਭੋਗਤਾ ਨੂੰ ਸੰਪਾਦਿਤ ਕਰ ਸਕਦਾ ਹੈ ਤਾਂ ਕਿਸੇ ਹੋਰ ਖਾਤੇ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾਉਣ ਲਈ user_id ਪਾਸ ਕਰੋ (edit_user ਸਮਰੱਥਾ)। ਅਣ-ਪ੍ਰਮਾਣਿਤ ਬੇਨਤੀਆਂ fc_api_forbidden ਵਾਪਸ ਕਰਦੀਆਂ ਹਨ। ਇੱਕ ਅਵੈਧ user_id fc_api_user_not_found ਵਾਪਸ ਕਰਦੀ ਹੈ।','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 { &quot;data&quot; ਦੇ ਨਾਲ: { ... } } ਜਦੋਂ ਹੈਂਡਲਰ ਇੱਕ ਪੇਲੋਡ ਵਾਪਸ ਕਰਦਾ ਹੈ।','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 { &quot;success&quot;: true } ਦੇ ਨਾਲ ਜਦੋਂ ਕੋਈ ਪੇਲੋਡ ਨਹੀਂ ਹੁੰਦਾ (ਉਦਾਹਰਨ ਲਈ DELETE)।','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ਅਸਫਲਤਾਵਾਂ WP_Error (ਕੋਡ, ਸੁਨੇਹਾ, data.status) ਤੋਂ WordPress REST ਗਲਤੀ JSON ਵਾਪਸ ਕਰਦੀਆਂ ਹਨ। ਵਾਇਰ ਕੋਡ fc_api_* ਪ੍ਰੀਫਿਕਸ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹਨ।','Forbidden access.' => 'ਮਨਾਹੀ ਪਹੁੰਚ।','Target user was not found.' => 'ਟੀਚਾ ਉਪਭੋਗਤਾ ਨਹੀਂ ਮਿਲਿਆ।','This feature is not available.' => 'ਇਹ ਵਿਸ਼ੇਸ਼ਤਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।','A required address field is missing.' => 'ਇੱਕ ਲੋੜੀਂਦਾ ਪਤਾ ਖੇਤਰ ਗੁੰਮ ਹੈ।','Postcode or ZIP is invalid.' => 'ਪੋਸਟਕੋਡ ਜਾਂ ਜ਼ਿਪ ਅਵੈਧ ਹੈ।','Phone number is invalid.' => 'ਫ਼ੋਨ ਨੰਬਰ ਅਵੈਧ ਹੈ।','State or county is invalid.' => 'ਰਾਜ ਜਾਂ ਕਾਉਂਟੀ ਅਵੈਧ ਹੈ।','Country is invalid or has no address fields.' => 'ਦੇਸ਼ ਅਵੈਧ ਹੈ ਜਾਂ ਇਸ ਵਿੱਚ ਕੋਈ ਪਤਾ ਖੇਤਰ ਨਹੀਂ ਹਨ।','The request could not be processed.' => 'ਬੇਨਤੀ &#39;ਤੇ ਕਾਰਵਾਈ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕੀ।','Back to previous step' => 'ਪਿਛਲੇ ਪੜਾਅ &#39;ਤੇ ਵਾਪਸ ਜਾਓ','Skip to settings' => 'ਸੈਟਿੰਗਾਂ &#39;ਤੇ ਜਾਓ','Start over and return to the first guided setup step' => 'ਦੁਬਾਰਾ ਸ਼ੁਰੂ ਕਰੋ ਅਤੇ ਪਹਿਲੇ ਗਾਈਡਡ ਸੈੱਟਅੱਪ ਪੜਾਅ &#39;ਤੇ ਵਾਪਸ ਜਾਓ','Start over' => 'ਸ਼ੁਰੂ ਤੋਂ ਸ਼ੁਰੂ ਕਰੋ','Please complete all sub-steps before continuing.' => 'ਜਾਰੀ ਰੱਖਣ ਤੋਂ ਪਹਿਲਾਂ ਕਿਰਪਾ ਕਰਕੇ ਸਾਰੇ ਉਪ-ਪੜਾਅ ਪੂਰੇ ਕਰੋ।','Expand' => 'ਫੈਲਾਓ','Collapse' => 'ਸਮੇਟਣਾ','Skip' => 'ਛੱਡੋ','Mark as complete' => 'ਮੁਕੰਮਲ ਵਜੋਂ ਨਿਸ਼ਾਨਦੇਹੀ ਕਰੋ','Mark as incomplete' => 'ਅਧੂਰੇ ਵਜੋਂ ਨਿਸ਼ਾਨਦੇਹੀ ਕਰੋ','View full-size image: %s' => 'ਪੂਰੇ ਆਕਾਰ ਦਾ ਚਿੱਤਰ ਵੇਖੋ: %s','Full-size setup guide image' => 'ਪੂਰੇ ਆਕਾਰ ਦਾ ਸੈੱਟਅੱਪ ਗਾਈਡ ਚਿੱਤਰ','Close image' => 'ਚਿੱਤਰ ਬੰਦ ਕਰੋ','Fluid Checkout Guided Setup' => 'ਤਰਲ ਚੈੱਕਆਉਟ ਗਾਈਡਡ ਸੈੱਟਅੱਪ','Welcome' => 'ਸਵਾਗਤ ਹੈ','Explore your checkout' => 'ਆਪਣੇ ਚੈੱਕਆਉਟ ਦੀ ਪੜਚੋਲ ਕਰੋ','All set' => 'ਸਭ ਤਿਆਰ ਹੈ','You do not have permission to access this page.' => 'ਤੁਹਾਨੂੰ ਇਸ ਪੰਨੇ ਤੱਕ ਪਹੁੰਚ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।','Go to step %1$d: %2$s' => 'ਕਦਮ %1$d &#39;ਤੇ ਜਾਓ: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ਇਹ ਗਾਈਡਡ ਸੈੱਟਅੱਪ ਤੁਹਾਨੂੰ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਤੋਂ ਜਾਣੂ ਕਰਵਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਹੇਠਾਂ ਦਿੱਤੇ ਕਦਮ ਹੁਣ ਲਈ ਪਲੇਸਹੋਲਡਰ ਹਨ।','Continue to the next step when you are ready.' => 'ਜਦੋਂ ਤੁਸੀਂ ਤਿਆਰ ਹੋਵੋ ਤਾਂ ਅਗਲੇ ਪੜਾਅ &#39;ਤੇ ਜਾਰੀ ਰੱਖੋ।','Open your store checkout to see Fluid Checkout in action.' => 'ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਨੂੰ ਕਾਰਵਾਈ ਵਿੱਚ ਦੇਖਣ ਲਈ ਆਪਣੇ ਸਟੋਰ ਚੈੱਕਆਉਟ ਨੂੰ ਖੋਲ੍ਹੋ।','View checkout page' => 'ਚੈੱਕਆਉਟ ਪੰਨਾ ਵੇਖੋ','You can return to Fluid Checkout settings to continue configuring your store.' => 'ਤੁਸੀਂ ਆਪਣੇ ਸਟੋਰ ਨੂੰ ਕੌਂਫਿਗਰ ਕਰਨਾ ਜਾਰੀ ਰੱਖਣ ਲਈ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਸੈਟਿੰਗਾਂ &#39;ਤੇ ਵਾਪਸ ਜਾ ਸਕਦੇ ਹੋ।','Review checkout and cart settings' => 'ਚੈੱਕਆਉਟ ਅਤੇ ਕਾਰਟ ਸੈਟਿੰਗਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ','Explore add-ons from the dashboard' => 'ਡੈਸ਼ਬੋਰਡ ਤੋਂ ਐਡ-ਆਨ ਦੀ ਪੜਚੋਲ ਕਰੋ','Finish & go to settings' => 'ਪੂਰਾ ਕਰੋ ਅਤੇ ਸੈਟਿੰਗਾਂ &#39;ਤੇ ਜਾਓ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ਸੰਮੇਲਨਾਂ ਨਾਲ ਮੇਲ ਕਰਨ ਲਈ ਪੁਰਾਣੇ ਮੁੱਲ ਤੋਂ ਬਿਲਿੰਗ ਫ਼ੋਨ ਫੀਲਡ ਦ੍ਰਿਸ਼ਟੀ ਵਿਕਲਪ ਨੂੰ ਅੱਪਡੇਟ ਕਰੋ।','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ਸੰਮੇਲਨਾਂ ਨਾਲ ਮੇਲ ਕਰਨ ਲਈ ਪੁਰਾਣੇ ਮੁੱਲ ਤੋਂ ਸ਼ਿਪਿੰਗ ਫੋਨ ਫੀਲਡ ਦ੍ਰਿਸ਼ਟੀ ਵਿਕਲਪ ਨੂੰ ਅੱਪਡੇਟ ਕਰੋ।','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ਆਰਡਰ ਸੰਖੇਪ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਸੈਟਿੰਗ ਨੂੰ ਨਵੇਂ ਸਪਲਿਟ ਡਿਜ਼ਾਈਨ ਸੈਕੰਡਰੀ ਕਾਲਮ ਬੈਕਗ੍ਰਾਊਂਡ ਰੰਗ ਵਿਕਲਪ ਵਿੱਚ ਕਾਪੀ ਕਰੋ।','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'ਬਾਈਟਸ਼ਿਪ ਪਲੱਗਇਨ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਵਧੀ ਹੋਈ ਚੋਣ ਖੇਤਰ ਵਿਸ਼ੇਸ਼ਤਾ ਹਮੇਸ਼ਾਂ ਅਯੋਗ ਹੁੰਦੀ ਹੈ।','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ਜਰਮਨ ਮਾਰਕੀਟ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਪਲੇਸ ਆਰਡਰ ਸਥਿਤੀ ਹਮੇਸ਼ਾਂ &quot;ਆਰਡਰ ਸਾਰਾਂਸ਼ ਦੇ ਹੇਠਾਂ&quot; ਤੇ ਸੈੱਟ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਉਸ ਪਲੱਗਇਨ ਲਈ ਪਲੇਸ ਆਰਡਰ ਬਟਨ ਅਤੇ ਕਾਨੂੰਨੀ ਚੈੱਕਬਾਕਸ ਨੂੰ ਆਰਡਰ ਸਾਰਾਂਸ਼ ਦੇ ਹੇਠਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce ਲਈ ਜਰਮਨਾਈਜ਼ਡ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਪਲੇਸ ਆਰਡਰ ਸਥਿਤੀ ਹਮੇਸ਼ਾਂ &quot;ਆਰਡਰ ਸੰਖੇਪ ਦੇ ਹੇਠਾਂ&quot; ਤੇ ਸੈੱਟ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਉਸ ਪਲੱਗਇਨ ਲਈ ਪਲੇਸ ਆਰਡਰ ਬਟਨ ਅਤੇ ਕਾਨੂੰਨੀ ਚੈੱਕਬਾਕਸ ਨੂੰ ਆਰਡਰ ਸੰਖੇਪ ਦੇ ਹੇਠਾਂ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਨ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।','Edit pickup locations' => 'ਪਿਕਅੱਪ ਟਿਕਾਣਿਆਂ ਦਾ ਸੰਪਾਦਨ ਕਰੋ','Use local pickup label from WooCommerce settings' => 'WooCommerce ਸੈਟਿੰਗਾਂ ਤੋਂ ਸਥਾਨਕ ਪਿਕਅੱਪ ਲੇਬਲ ਦੀ ਵਰਤੋਂ ਕਰੋ','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ਜਦੋਂ ਸਮਰੱਥ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਚੈੱਕਆਉਟ &#39;ਤੇ ਪਿਕਅੱਪ ਵਿਕਲਪ ਲੇਬਲ WooCommerce ਪਿਕਅੱਪ ਸਥਾਨ ਸੈਟਿੰਗਾਂ ਤੋਂ ਸਿਰਲੇਖ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ। ਜਦੋਂ ਅਯੋਗ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਲੇਬਲ ਫਲੂਇਡ ਚੈੱਕਆਉਟ ਤੋਂ ਅਨੁਵਾਦਯੋਗ &quot;ਸਥਾਨਕ ਪਿਕਅੱਪ&quot; ਟੈਕਸਟ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ।','Button label for applying coupon codesApply' => 'ਲਾਗੂ ਕਰੋ','Checkout step titleContact' => 'ਸੰਪਰਕ','Checkout step titleShipping' => 'ਸ਼ਿਪਿੰਗ','Checkout step titleBilling' => 'ਬਿਲਿੰਗ','Checkout step titlePayment' => 'ਭੁਗਤਾਨ','Checkout substep change link labelChange' => 'ਬਦਲੋ','Checkout substep save link labelSave changes' => 'ਬਦਲਾਅ ਸੁਰੱਖਿਅਤ ਕਰੋ','Substep review textNone.' => 'ਕੋਈ ਨਹੀਂ।','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'ਕੋਈ ਚਿੱਤਰ ਨਹੀਂ ਚੁਣਿਆ ਗਿਆ।','Settings sectionCart' => 'ਕਾਰਟ','Settings sectionOrder pay' => 'ਆਰਡਰ ਪੇ','Settings sectionThank you' => 'ਤੁਹਾਡਾ ਧੰਨਵਾਦ','Settings section titleIntegrations' => 'ਏਕੀਕਰਨ','Settings section titleLicense keys' => 'ਲਾਇਸੈਂਸ ਕੁੰਜੀਆਂ','Captcha positionBefore place order section' => 'ਆਰਡਰ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਵਾਲਾ ਭਾਗ','Captcha positionBefore place order button' => 'ਆਰਡਰ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਬਟਨ','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'ਬੰਦ ਕਰੋ','Log in link label at checkout contact stepLog in' => 'ਲਾਗਿਨ','Log in separator label at for when guest checkout is disabledOr continue below' => 'ਜਾਂ ਹੇਠਾਂ ਜਾਰੀ ਰੱਖੋ','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'ਜਾਂ ਮਹਿਮਾਨ ਵਜੋਂ ਜਾਰੀ ਰੱਖੋ','Clear image selection on admin pages.Remove image' => 'ਚਿੱਤਰ ਹਟਾਓ','shipping packagesShipping %d' => 'ਸ਼ਿਪਿੰਗ %d','shipping packagesShipping' => 'ਸ਼ਿਪਿੰਗ','Used as fallback for "